return ['domain'=>'lingua-forge','plural-forms'=>'nplurals=3; plural=(n==1 ? 0 : n%10 >= 2 && n%10<=4 &&(n%100<10||n%100 >= 20)? 1 : 2);','language'=>'pl_PL','project-id-version'=>'Lingua Forge 2.1.0','pot-creation-date'=>'2026-07-21T23:33:36+00:00','po-revision-date'=>'2026-07-05 22:53+0000','x-generator'=>'Loco https://localise.biz/','messages'=>['Lingua Forge'=>'Lingua Forge','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, complete multilingual SEO (hreflang, Open Graph, Schema.org, sitemap), and AI content tools for WordPress. Language detection, URL routing, translation, content generation, and a full SEO layer — no companion plugin required.'=>'Wielojęzyczne routingi, pełne wielojęzyczne SEO (hreflang, Open Graph, Schema.org, mapa strony), oraz narzędzia AI do tworzenia treści dla WordPressa. Wykrywanie języka, routingi URL, tłumaczenia, generowanie treści i pełna warstwa SEO — bez konieczności posiadania dodatkowego wtyczki.','Uli Hake'=>'Uli Hake','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'Tłumacz','Lingua Forge — Quick Translate'=>'Lingua Forge — Szybkie tłumaczenie','Informative'=>'Informacyjne','Persuasive'=>'Przekonywujące','Storytelling'=>'Opowiadanie','Technical'=>'Techniczne','Conversational'=>'Konwersacyjne','Permission denied.'=>'Odmowa dostępu.','Cannot determine target language from slug.'=>'Nie można określić docelowego języka na podstawie slug.','Invalid post type.'=>'Nieprawidłowy typ wpisu.','Invalid or primary language.'=>'Nieprawidłowy lub główny język.','Template not found or not stored in the database.'=>'Szablon nie został znaleziony lub nie jest zapisany w bazie danych.','Template has no content.'=>'Szablon nie ma treści.','No internal links found to update.'=>'Nie znaleziono wewnętrznych linków do aktualizacji.','%d link updated.'=>'%d link zaktualizowany.' . "\0" . '%d linków zaktualizowanych.' . "\0" . '%d link zaktualizowany.','No language-specific template parts found to map.'=>'Nie znaleziono części szablonu specyficznych dla języka do mapowania.','No template part references needed updating.'=>'Nie ma potrzeby aktualizacji odwołań do części szablonu.','%d part reference updated.'=>'%d odwołanie do części zaktualizowane.' . "\0" . '%d odwołań do części zaktualizowanych.' . "\0" . '%d odwołanie do części zaktualizowane.','Invalid language.'=>'Nieprawidłowy język.','Template part not found or not stored in the database.'=>'Część szablonu nie została znaleziona lub nie jest zapisana w bazie danych.','Template part has no content.'=>'Część szablonu nie ma treści.','No navigation references needed updating.'=>'Nie ma potrzeby aktualizacji odwołań do nawigacji.','%d navigation reference updated.'=>'%d odwołanie do nawigacji zaktualizowane.' . "\0" . '%d odwołań do nawigacji zaktualizowanych.' . "\0" . '%d odwołanie do nawigacji zaktualizowane.','No AI provider configured.'=>'Nie skonfigurowano dostawcy AI.','Missing pattern name or language.'=>'Brak nazwy wzoru lub języka.','Pattern not found.'=>'Wzór nie został znaleziony.','Pattern has no content to translate.'=>'Wzór nie ma treści do tłumaczenia.','AI provider returned an empty response.'=>'Dostawca AI zwrócił pustą odpowiedź.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Wzór został przetłumaczony i zapisany. Skopiuj treść do swojego wpisu CPT za pomocą edytora bloków lub użyj go jako punktu wyjścia dla wielokrotnego bloku.','%d template repaired.'=>'%d szablon naprawiony.' . "\0" . 'Naprawiono %d szablonów.' . "\0" . '%d szablonów naprawiony.','All template metadata is already up to date.'=>'Metadane wszystkich szablonów są już aktualne.','Invalid template type.'=>'Nieprawidłowy typ szablonu.','Template "%s" already exists.'=>'Szablon "%s" już istnieje.','Fix Links'=>'Napraw linki','Fix Parts'=>'Napraw części','Re-create'=>'Odtwórz','"%s" recreated.'=>'"%s" odtworzony.','"%s" created.'=>'"%s" został utworzony.','Invalid template part.'=>'Nieprawidłowa część szablonu.','Template part "%s" already exists.'=>'Część szablonu "%s" już istnieje.','Fix Nav'=>'Napraw nawigację','"%1$s" recreated. %2$d template updated.'=>'"%1$s" odtworzony. %2$d szablon zaktualizowany.' . "\0" . '"%1$s" odtworzony. %2$d szablonów zaktualizowanych.' . "\0" . '"%1$s" odtworzony. %2$d szablonów zaktualizowanych.','"%1$s" created. %2$d template updated.'=>'"%1$s" został utworzony. %2$d szablonów zaktualizowanych.' . "\0" . '"%1$s" został utworzony. %2$d szablonów zaktualizowanych.' . "\0" . '"%1$s" został utworzony. %2$d szablonów zaktualizowanych.','Page'=>'Strona','Single'=>'Pojedynczy','Search'=>'Szukaj','Search Results'=>'Wyniki wyszukiwania','Archive'=>'Archiwum','Front Page'=>'Strona główna','Blog Home'=>'Strona główna bloga','Single: %s'=>'Pojedynczy: %s','Single %s'=>'Pojedynczy %s','Archive: %s'=>'Archiwum: %s','%s Archive'=>'%s Archiwum','No source content found to translate.'=>'Nie znaleziono treści źródłowej do tłumaczenia.','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Przetłumaczono. Przejrzyj w Edytorze Stron — linki wewnętrzne, adresy URL nawigacji i szablony nie są automatycznie aktualizowane.','Navigation not found.'=>'Nawigacja nie znaleziona.','Navigation has no content to translate.'=>'Nawigacja nie zawiera treści do tłumaczenia.','"%1$s %2$s" saved.'=>'"%1$s %2$s" zapisano.','SEO Analysis'=>'Analiza SEO','Profile'=>'Profil','Details ↗'=>'Szczegóły ↗','/ 100'=>'/ 100','Overall SEO score'=>'Ogólna ocena SEO','Metric'=>'Metryka','Finding'=>'Wyszukiwanie','Title'=>'Tytuł','Meta description'=>'Meta opis','Word count'=>'Liczba słów','Reading time'=>'Czas czytania','Headings'=>'Nagłówki','Images'=>'Obrazy','Links'=>'Linki','AI Recommendations'=>'Rekomendacje AI','Run AI Analysis'=>'Uruchom analizę AI','Analyzing…'=>'Analiza…','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'Skonfiguruj dostawcę AI w Ustawienia → Klucze API, aby włączyć rekomendacje oparte na AI.','AI analysis failed. Please try again.'=>'Analiza AI nie powiodła się. Spróbuj ponownie.','Suggested title'=>'Sugerowany tytuł','Suggested meta description'=>'Sugerowany meta opis','Loaded from cache.'=>'Wczytano z pamięci podręcznej.','↺ Refresh AI Analysis'=>'Odśwież analizę AI ↺','Analyse…'=>'Analiza…','Analysis request failed. Please try again.'=>'Żądanie analizy nie powiodło się. Spróbuj ponownie.','No translation found — analyzed the source language version.'=>'Nie znaleziono tłumaczenia — przeanalizowano wersję językową źródłową.','Translate page…'=>'Tłumacz stronę…','Generate content…'=>'Generuj treść…','AI Behaviour Preset'=>'Predefiniowany zachowanie AI','Custom'=>'Niestandardowe','Global default (%s)'=>'Domyślny globalny (%s)','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Nadpisuje preset AI dla tłumaczenia i generowania treści na tej stronie. Instrukcje niestandardowe dla całej witryny (Ustawienia → Zachowanie) są zawsze dodawane do każdego żądania, niezależnie od tego wyboru.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Nadpisuje preset AI dla tłumaczenia i generowania treści na tej stronie. Wszystkie inne funkcje zawsze korzystają z globalnego preset.','Close'=>'Zamknij','Translate missing'=>'Brak tłumaczenia','From'=>'Od','Retranslate'=>'Przetłumacz ponownie','Retranslate every other language version from this post. Creates any that are missing and overwrites any that already exist — including the primary language, if this post is a translation.'=>'Przetłumaczy ponownie każdą inną wersję językową tego wpisu. Tworzy brakujące i nadpisuje istniejące — w tym język podstawowy, jeśli ten wpis jest tłumaczeniem.','Sync'=>'Synchronizuj','Reassign the correct language-specific template to every existing translation of this post. No AI call and no content changes — free and safe to run any time.'=>'Przypisz prawidłowy szablon specyficzny dla języka do każdego istniejącego tłumaczenia tego wpisu. Bez wołania AI i bez zmian treści — bezpłatne i bezpieczne do uruchomienia w dowolnym momencie.','Template Sync — reassign templates for every translation'=>'Synchronizacja szablonu — ponownie przypisz szablony dla każdego tłumaczenia','TS'=>'SS','Last rule-based SEO score. Run analysis in Settings → SEO → Analysis to update.'=>'Ostatni wynik SEO oparty na regułach. Uruchom analizę w Ustawienia → SEO → Analiza, aby zaktualizować.','Translating…'=>'Tłumaczenie w toku…','Retranslating…'=>'Ponowne tłumaczenie…','Syncing…'=>'Synchronizowanie…','This retranslates every other language version of this post from this one — creating any that are missing and overwriting any that already exist (including the primary language, if this post is a translation). This cannot be undone. Continue?'=>'Przetłumaczy ponownie każdą inną wersję językową tego wpisu — tworząc brakujące i nadpisując istniejące (w tym język podstawowy, jeśli ten wpis jest tłumaczeniem). Nie można tego cofnąć. Kontynuować?','Syncing templates…'=>'Synchronizowanie szablonów…','✓ Done'=>'✓ Zrobione','Error'=>'Błąd','Navigation posts are translated via the Router tab, not this button.'=>'Posty nawigacji są tłumaczone przez zakładkę Router, a nie tym przyciskiem.','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Tworzenie tłumaczeń dla typu posta "%s" wymaga aktywnej integracji. Upewnij się, że wymagana integracja jest zainstalowana i aktywna.','No %s version found in this translation group.'=>'Nie znaleziono wersji %s w tej grupie tłumaczeń.','Sync from a secondary-language WooCommerce product is disabled by default, since it would overwrite the primary product. Enable it in Settings → Behavior → WooCommerce if you want a translation to be able to become the new source content.'=>'Synchronizacja z produktu WooCommerce w języku wtórnym jest domyślnie wyłączona, ponieważ nadpisałaby główny produkt. Włącz to w Ustawienia → Zachowanie → WooCommerce, jeśli chcesz, aby tłumaczenie mogło stać się nową treścią źródłową.','Sync from a secondary-language post is disabled by default, since it would overwrite the primary post. Enable it in Settings → Behavior → Sync if you want a translation to be able to become the new source content.'=>'Synchronizacja z wpisu w języku wtórnym jest domyślnie wyłączona, ponieważ nadpisałaby główny wpis. Włącz to w Ustawienia → Zachowanie → Synchronizacja, jeśli chcesz, aby tłumaczenie mogło stać się nową treścią źródłową.','Skipped — you do not have permission to edit the existing translation.'=>'Pominięto — nie masz uprawnień do edycji istniejącego tłumaczenia.','Creating translations for post type "%s" requires an active integration.'=>'Tworzenie tłumaczeń dla typu wpisu "%s" wymaga aktywnej integracji.','Template Sync can only be run from the primary/source-language post.'=>'Synchronizacja szablonu może być uruchamiana tylko z głównego/źródłowego wpisu w języku.','Skipped — you do not have permission to edit this translation.'=>'Pominięto — nie masz uprawnień do edycji tego tłumaczenia.','Translation Caching'=>'Buforowanie tłumaczeń','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge używa dwóch niezależnych warstw pamięci podręcznej, aby uniknąć zbędnych wywołań API AI. Użyj poniższych zakładek, aby sprawdzić i zarządzać każdą z nich.','API Response Cache'=>'Pamięć podręczna odpowiedzi API','Translation Memory'=>'Pamięć tłumaczeń','(disabled)'=>'wyłączone','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Entries are invalidated automatically when the content or AI provider/model changes.'=>'Pamięć podręczna dla każdego wpisu dla tłumaczeń generowanych przez AI, opisów meta, fragmentów i treści. Pozycje są automatycznie unieważniane, gdy treść lub dostawca/model AI się zmieniają.','Enable API response caching'=>'Włącz buforowanie odpowiedzi API','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them.'=>'Pamięć podręczna odpowiedzi API przechowuje surowy wynik każdego żądania AI — tłumaczenie, opis meta, fragment i generowanie treści — kluczem jest hash wejść (treść, para języków, dostawca, model). Wyłącz podczas dostrajania promptów lub gdy potrzebujesz, aby każde żądanie dotarło do dostawcy AI. Wyłączenie nie usuwa zapisanych wpisów — ponowne włączenie je przywraca.','Save'=>'Zapisz','Cached API responses'=>'Zapisane odpowiedzi API','API calls saved by cache'=>'Wywołania API zapisane w pamięci podręcznej','(avg %.1f hits/entry)'=>'(średnio %.1f trafień/pozycję)','Oldest cached response'=>'Najstarsza zapisana odpowiedź','Most recent cached response'=>'Ostatnia zapisana odpowiedź','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Czy wyczyścić wszystkie zapisane wyniki AI? Przyszłe żądania będą wywoływać nowe wywołania API, aż do odbudowania pamięci podręcznej.','Clear API Response Cache'=>'Wyczyść pamięć podręczną odpowiedzi API','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Glossary edits and Compliance preset changes automatically invalidate affected cached translations.'=>'Pamięć podręczna tłumaczeń na poziomie bloków współdzielona między wpisami. Gdy włączona, identyczne bloki (ta sama składnia, para języków i glosariusz) są serwowane z pamięci zamiast ponownego wywołania AI. Edycje glosariusza i zmiany presetów zgodności automatycznie unieważniają odpowiednie zapisane tłumaczenia.','Enable block-level translation cache reuse across posts'=>'Włącz ponowne użycie pamięci podręcznej tłumaczeń na poziomie bloków między wpisami','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Obecnie pomijane dla wpisów korzystających z atrybutów blok-comment (np. wp:details, pola podsumowania) — przechodzą do istniejącej ścieżki tłumaczenia wywołania pojedynczego.','Cached block translations'=>'Zapisane tłumaczenia bloków','Block translation reuses'=>'Ponowne użycie tłumaczeń bloków','(avg %.1f hits/block)'=>'(średnio %.1f trafień/blok)','Oldest cached block'=>'Najstarszy zapisany blok','Most recent cached block'=>'Ostatni zapisany blok','Approximate size'=>'Przybliżony rozmiar','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Wyczyścić całą pamięć tłumaczeń? Przyszłe tłumaczenia odbudują pamięć podręczną podczas ich wykonywania.','Clear Translation Memory'=>'Wyczyść pamięć tłumaczeń','API Response Cache setting saved.'=>'Ustawienie pamięci podręcznej odpowiedzi API zapisane.','Translation Memory setting saved.'=>'Ustawienie pamięci tłumaczeń zapisane.','AI cache cleared. %d entry was removed.'=>'Pamięć podręczna AI wyczyszczona. %d wpis został usunięty.' . "\0" . 'Pamięć podręczna AI wyczyszczona. %d wpisów zostało usuniętych.' . "\0" . 'Pamięć podręczna AI wyczyszczona. %d wpisy zostały usunięte.','Translation Memory cleared. %d cached block was removed.'=>'Pamięć tłumaczeń wyczyszczona. Usunięto %d zbuforowanych bloków.' . "\0" . 'Pamięć tłumaczeń wyczyszczona. Usunięto %d zbuforowanych bloków.' . "\0" . 'Pamięć tłumaczeń wyczyszczona. Usunięto %d zbuforowanych bloków.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'Lingua Forge to kompletne rozwiązanie SEO wielojęzycznego. Nie jest wymagana żadna dodatkowa wtyczka SEO.','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'Jeśli masz zainstalowaną ogólną wtyczkę SEO, ten panel pokazuje, jak LF dostosowuje się, aby uniknąć duplikacji outputu. Celem jest unikanie kolizji — nie współpraca. LF zawsze zapewnia wielojęzyczną warstwę SEO (hreflang, og:locale, schema inLanguage), która wymaga znajomości konfiguracji routingu językowego LF, aby poprawnie generować.','Installed SEO plugins'=>'Zainstalowane wtyczki SEO','Plugin'=>'Wtyczka','Status'=>'Status','✓ Active'=>'✓ Aktywne','— Not detected'=>'— Nie wykryto','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'Nie wykryto kolidujących wtyczek SEO. Lingua Forge obsługuje cały output SEO niezależnie.','What LF provides — and collision avoidance'=>'Co zapewnia LF — i unikanie kolizji','Feature'=>'Funkcja','LF provides'=>'LF zapewnia','When another SEO plugin is installed'=>'Gdy zainstalowana jest inna wtyczka SEO','Hreflang'=>'Hreflang','Disabled (by setting)'=>'Wyłączone (ustawieniem)','✓ LF outputs — plugin hreflang suppressed'=>'✓ Wyniki LF — ukrycie hreflang przez wtyczkę','✓ LF outputs'=>'✓ Wyniki LF','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'LF generuje dokładne tagi hreflang dla każdego skonfigurowanego języka, w tym x-default. Wtyczki SEO ogólne nie mają dostępu do konfiguracji routingu LF i mogą generować hreflang na podstawie błędnych założeń URL. LF tłumi ich wyjście za pomocą filtra, aby zapobiec kolizjom.','Suppressed: %s.'=>'Wyłączone: %s.','Open Graph'=>'Open Graph','Disabled (mode setting)'=>'Wyłączone (trybem ustawienia)','→ Locale tags only — deferring base OG to plugin'=>'→ Tagi lokalizacji tylko — odroczenie podstawowego OG do wtyczki','→ Locale tags only (manual setting)'=>'→ Tagi lokalizacji tylko (ustawienie ręczne)','✓ LF outputs full OG + Twitter Cards'=>'✓ Wyniki LF pełne OG + Karty Twittera','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'LF zawsze dodaje og:locale i og:locale:alternate — wielojęzyczne sygnały OG, które żadna ogólna wtyczka SEO nie może poprawnie wygenerować. Dla podstawowego zestawu OG (og:title, og:description, og:image) LF go generuje, gdy nie ma innej wtyczki. Gdy zainstalowana jest wtyczka SEO, LF pomija podstawowy zestaw, aby uniknąć duplikacji tagów — nie dlatego, że wtyczka jest "lepsza", ale ponieważ duplikacja nie ma wartości.','Schema.org JSON-LD'=>'JSON-LD Schema.org','— Deferred to plugin'=>'— Przekierowane do wtyczki','✓ LF outputs Article / WebPage / WebSite'=>'✓ Wyniki LF artykuł / strona internetowa / witryna','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'LF generuje wielojęzyczny JSON-LD z adnotacjami inLanguage powiązanymi z konfiguracją routingu językowego. Gdy zainstalowana jest wtyczka SEO, LF całkowicie wyłącza własny schemat: duplikaty grafów JSON-LD powodują błędy walidacji, a nie ma czystego sposobu na uzupełnienie istniejącego grafu.','XML Sitemap'=>'Mapa XML','✓ Active at /lf-sitemap.xml'=>'✓ Aktywne w /lf-sitemap.xml','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'LF generuje własną mapę witryny z alternatywami xhtml:link dla wszystkich grup tłumaczeń. Gdy zainstalowana jest wtyczka SEO, generuje osobną mapę — obie współistnieją niezależnie. Prześlij obie do Google Search Console: mapa witryny wtyczki SEO do odkrywania treści, mapa witryny LF do sygnałów relacji językowych.','Canonical tag'=>'Tag kanoniczny','✓ WP canonical replaced (self-referencing)'=>'✓ Zastąpiono kanoniczny URL WP (odwołujący się do siebie)','WP core canonical active (hreflang disabled)'=>'Włączony kanoniczny WP (hreflang wyłączony)','LF removes the WordPress core canonical tag and replaces it with a self-referencing canonical pointing to the correct language-prefixed URL. When a third-party SEO plugin (Yoast, Rank Math, AIOSEO, SEOPress) is active, LF defers canonical management to that plugin entirely.'=>'LF usuwa kanoniczny tag WordPress i zastępuje go odwołującym się do siebie kanonicznym odwołaniem wskazującym na poprawny URL z prefiksem językowym. Gdy aktywna jest wtyczka SEO innej firmy (Yoast, Rank Math, AIOSEO, SEOPress), LF całkowicie przekazuje zarządzanie kanonicznym do tej wtyczki.','Legacy lf-social-share mu-plugin'=>'Legacy mu-plugin lf-social-share','The lf-social-share mu-plugin is active.'=>'Wtyczka mu lf-social-share jest aktywna.','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'Wbudowane moduły Social Share i Open Graph Lingua Forge obejmują całą funkcjonalność, którą zapewnia mu-plugin, plus obsługę wielojęzycznego og:locale. Możesz bezpiecznie dezaktywować mu-plugin.','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'Tagi OG/Twitter Card: obsługiwane przez moduł Open Graph LF (SEO → Open Graph & Twitter Cards)','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'Udostępnianie bloków ikon społecznościowych: adresy URL: obsługiwane przez wbudowane udostępnianie społecznościowe LF (SEO → Udostępnianie społecznościowe)','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'akcje JS kopiowania/natywne/auto: obsługiwane przez social-share.js LF','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'Podczas aktywności, wtyczka mu obsługuje podstawowy zestaw OG, a LF emituje tylko tagi lokalizacji (tryb automatyczny). Usunięcie go automatycznie przełącza LF na pełny tryb OG.','Debug Files'=>'Pliki debugowania','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Gdy włączone jest logowanie debugowania (za pomocą przełącznika poniżej lub przez zdefiniowanie LINGUAFORGE_AI_DEBUG w wp-config.php), funkcje tłumaczenia i tłumaczenia szablonów FSE zapisują swoje surowe podpowiedzi AI i odpowiedzi na dysk w celach diagnostycznych. Użyj tej sekcji, aby monitorować ten output i wyczyścić go, gdy będziesz miał to, czego potrzebujesz — pliki mogą szybko się powiększać na dużych stronach. Skonfiguruj katalog docelowy za pomocą filtra linguaforge_debug_dir.','Debug files cleared. %d file was removed.'=>'Pliki debugowania wyczyszczone. Usunięto %d plik.' . "\0" . 'Pliki debugowania wyczyszczone. Usunięto %d plików.' . "\0" . 'Pliki debugowania wyczyszczone. Usunięto %d pliki.','Debug logging enabled.'=>'Logowanie debugowania włączone.','Debug logging disabled.'=>'Logowanie debugowania wyłączone.','Debug logging'=>'Logowanie debugowania','Write AI prompts and responses to disk for troubleshooting'=>'Zapisuj podpowiedzi i odpowiedzi AI na dysk w celach diagnostycznych','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Wymuszone włączenie przez stałą LINGUAFORGE_AI_DEBUG w wp-config.php. Usuń tę linię, aby kontrolować ten przełącznik stąd.','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Wymuszone wyłączenie przez stałą LINGUAFORGE_AI_DEBUG w wp-config.php. Usuń tę linię, aby kontrolować ten przełącznik stąd.','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Pliki trafiają do poniższego katalogu. Przydatne do diagnozowania problemów z tłumaczeniem — wyłącz po uzyskaniu potrzebnych danych, aby pliki się nie gromadziły. Możesz też wymusić to z wp-config.php za pomocą `define( \'LINGUAFORGE_AI_DEBUG\', true );`, co nadpisuje ten przełącznik.','Currently:'=>'Obecnie:','✓ Enabled'=>'✓ Włączone','✗ Disabled'=>'✗ Wyłączone','Directory'=>'Katalog','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filtruj za pomocą linguaforge_debug_dir, aby przekierować wyjście debugowania do niepublicznej lokalizacji.','Files'=>'Pliki','.txt file(s) in the directory'=>'.txt plik(i) w katalogu','Save Debug Setting'=>'Zapisz ustawienia debugowania','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Czy chcesz usunąć wszystkie pliki .txt w katalogu debugowania? Sam katalog pozostanie, aby przyszłe zapisy debugowania mogły się tam trafiać.','Clear Debug Files'=>'Wyczyść pliki debugowania','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'Lingua Forge generuje tagi <link rel="alternate" hreflang> dla każdego skonfigurowanego języka na każdej stronie, w tym x-default wskazujący na język źródłowy. To główny sygnał SEO wielojęzycznego dla Google i innych wyszukiwarek — nie jest wymagana dodatkowa wtyczka SEO.','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'Gdy aktywne są Yoast SEO, Rank Math, All in One SEO lub SEOPress, Lingua Forge automatycznie wyłącza ich generowanie hreflang za pomocą filtra. Ogólne wtyczki SEO generują hreflang na podstawie struktury URL jednolanguage i nie mogą uwzględnić Twojej konfiguracji routingu wielojęzycznego; wyjście LF jest zawsze poprawne.','Hreflang settings saved.'=>'Ustawienia hreflang zapisane.','Hreflang output'=>'Wynik hreflang','Output hreflang tags in wp_head'=>'Wynik tagów hreflang w wp_head','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'Wyłącz tylko dla stron headless lub w pełni niestandardowych implementacji hreflang. Po wyłączeniu LF nie usuwa już kanonicznego tagu WordPressa i nie tłumi outputu hreflang wtyczek SEO.','Current status'=>'Aktualny status','✓ Hreflang active'=>'✓ Hreflang aktywne','LF is outputting hreflang tags and is replacing the WordPress core canonical with a self-referencing canonical for each language version.'=>'LF wyświetla tagi hreflang i zastępuje kanoniczny tag WordPress core samoodwołującym się tagiem kanonicznym dla każdej wersji językowej.','LF is suppressing hreflang output from: %s'=>'LF tłumi output hreflang z: %s','Save Hreflang Settings'=>'Zapisz ustawienia Hreflang','Language Overrides'=>'Nadpisywanie języka','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Prześlij skompilowane pliki .mo, aby nadpisać teksty wtyczek innych firm dla określonych lokalizacji — na przykład własne tłumaczenie VikBooking, które używa "mieszkanie" zamiast "pokój". Pliki muszą mieć nazwę zgodną z konwencją WordPress: {textdomain}-{locale}.mo (np. vikbooking-ca.mo). Są przechowywane w folderze uploads i przetrwają aktualizacje wtyczek.','Override file uploaded successfully.'=>'Nadpisanie pliku zostało pomyślnie przesłane.','Override file deleted.'=>'Plik nadpisania został usunięty.','No file was selected.'=>'Nie wybrano pliku.','Only .mo files are accepted.'=>'Akceptowane są tylko pliki .mo.','The upload failed — please try again.'=>'Przesyłanie nie powiodło się — spróbuj ponownie.','Could not save the file. Check that the uploads folder is writable.'=>'Nie można zapisać pliku. Sprawdź, czy folder uploads jest zapisywalny.','Invalid filename.'=>'Nieprawidłowa nazwa pliku.','Security check failed — file path is not permitted.'=>'Nieudana kontrola bezpieczeństwa — ścieżka pliku jest niedozwolona.','An unknown error occurred.'=>'Wystąpił nieznany błąd.','Text domain / locale'=>'Tekst domeny / lokalizacja','Size'=>'Rozmiar','Delete all files for this override (both .mo and .po)?'=>'Usunąć wszystkie pliki dla tego nadpisania (zarówno .mo, jak i .po)?','Delete'=>'Usuń','No override files uploaded yet.'=>'Jeszcze nie przesłano żadnych plików nadpisujących.','Upload .mo file'=>'Prześlij plik .mo','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Akceptuje tylko skompilowane pliki .mo. Nazwa pliku musi mieć wzór {textdomain}-{locale}.mo. Przesłanie pliku o tej samej nazwie co istniejący spowoduje jego zastąpienie.','Upload Override'=>'Prześlij nadpisanie','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Kopiuj do bezpiecznej pamięci','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate przechowuje własne tłumaczenia w wp-content/languages/loco/ — lokalizacji, którą można cicho wyczyścić podczas aktualizacji WP, reinstalacji wtyczki lub usunięcia Loco Translate. Kopiowanie plików tutaj przenosi je do katalogu Lingua Forge i18n-overrides, który przetrwa te wszystkie zdarzenia i jest automatycznie ładowany przy każdym żądaniu.','File copied to safe storage successfully.'=>'Plik skopiowany do bezpiecznej pamięci pomyślnie.','Source file not found.'=>'Nie znaleziono pliku źródłowego.','Could not copy the file. Check that the uploads folder is writable.'=>'Nie można skopiować pliku. Sprawdź, czy folder uploads jest zapisywalny.','Invalid file reference.'=>'Nieprawidłowe odniesienie do pliku.','Type'=>'Typ','✓ In safe storage'=>'✓ W bezpiecznej pamięci','Copy to safe storage'=>'Kopiuj do bezpiecznej pamięci','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Jeszcze nie znaleziono własnych plików Loco Translate. Pojawią się tutaj po zapisaniu tłumaczenia w Loco Translate.','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'Lingua Forge generuje meta tagi Open Graph i Twitter Card, dzięki czemu udostępniane URL-e wyświetlają poprawny język, tytuł, opis i obraz na platformach społecznościowych.','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'W przeciwieństwie do hreflang — gdzie LF zawsze nadpisuje inne wtyczki, ponieważ nie mogą znać Twojej konfiguracji wielojęzycznej — Open Graph jest inny: Yoast, Rank Math i podobne wtyczki już generują poprawne tagi OG dla Twojej treści. Duplikowanie ich nie dodaje wartości. W trybie automatycznym LF wykrywa aktywne wtyczki SEO i dodaje tylko to, czego nie mogą dostarczyć: og:locale (bieżący język) i og:locale:alternate (wszystkie inne skonfigurowane języki).','Open Graph settings saved.'=>'Ustawienia Open Graph zapisane.','Open Graph output'=>'Wynik Open Graph','Output Open Graph tags in wp_head'=>'Wynik tagów Open Graph w wp_head','Output mode'=>'Tryb wyjścia','Auto (recommended)'=>'Auto (zalecane)','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'Wykrywanie aktywnych wtyczek SEO (Yoast, Rank Math itp.) podczas działania. Emituj tylko og:locale + og:locale:alternate, gdy inna wtyczka już generuje pełny zestaw OG; emituj pełny zestaw, gdy żadna nie jest wykryta.','Locale only'=>'Tylko lokalizacja','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'Zawsze emituj tylko og:locale i og:locale:alternate. Używaj, gdy inna wtyczka lub motyw obsługuje pełny zestaw OG.','Full'=>'Pełne','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'Zawsze emituj pełny zestaw OG + Twitter Card, niezależnie od innych wtyczek. Używaj tylko, jeśli żadna inna wtyczka nie generuje tagów OG.','Disabled'=>'Wyłączone','Do not output any OG tags.'=>'Nie generuj żadnych tagów OG.','Default OG image'=>'Domyślny obraz OG','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'Adres URL obrazka zastępczego używany, gdy strona nie ma wyróżnionego obrazu, logo witryny lub ikonę witryny. Wyświetlany w podglądach społecznościowych dla archiwów, indeksu bloga i dowolnej pojedynczej strony bez miniatury.','— Disabled'=>'— Wyłączone','✓ Active — locale tags only (og:locale, og:locale:alternate)'=>'✓ Aktywne — tagi lokalizacji tylko (og:locale, og:locale:alternate)','✓ Active — full OG + Twitter Cards'=>'✓ Aktywne — pełne OG + Karty Twittera','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'Wykryto legacy mu-plugin lf-social-share. LF odracza podstawowy zestaw OG do mu-plugin i generuje tylko og:locale + og:locale:alternate. Możesz dezaktywować mu-plugin — wbudowany Social Share LF (zakładka SEO → Social Share) i Open Graph pokrywają tę samą funkcjonalność.','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'Wykryto wtyczkę(i) SEO: %s. LF wyświetla tylko og:locale i og:locale:alternate; wykryta wtyczka obsługuje pełny zestaw OG.','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'Nie wykryto zewnętrznej wtyczki OG. LF generuje pełny zestaw OG + Twitter Card.','Save Open Graph Settings'=>'Zapisz ustawienia Open Graph','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'Lingua Forge generuje dane strukturalne JSON-LD Schema.org, aby wyszukiwarki rozumiały typ treści, język i metadane. To główny sposób komunikacji adnotacji inLanguage dla treści wielojęzycznych z Google i innymi robotami.','Schema output deferred.'=>'Wynik schematu odroczony.','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'%s jest aktywne i już generuje Schema.org JSON-LD. Lingua Forge wyłączyło własne wyjście schematu, aby zapobiec konfliktom grafów. W przeciwieństwie do Open Graph — gdzie LF dodaje og:locale na podstawie innej wtyczki — schemat nie może być czysto uzupełniony: duplikaty lub nakładające się grafy JSON-LD powodują błędy walidacji. Wyłącz wyjście schematu w wykrytej wtyczce, jeśli chcesz, aby LF obsługiwał dane strukturalne.','Schema.org settings saved.'=>'Ustawienia schema.org zapisane.','Schema.org output'=>'Wynik schema.org','Output Schema.org JSON-LD in wp_head'=>'Wypisz schemat JSON-LD Schema.org w wp_head','Locked — a conflicting SEO plugin is active. See the notice above.'=>'Zablokowane — aktywna jest kolidująca wtyczka SEO. Zobacz powiadomienie powyżej.','Article / WebPage'=>'Artykuł / Strona internetowa','Output Article or WebPage schema on singular posts and pages'=>'Wynik schematu Article lub WebPage na pojedynczych postach i stronach','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'Posty na blogu używają Article; wszystkie inne typy postów i strony używają WebPage. Zawiera nagłówek, opis, inLanguage, url, datePublished, dateModified, obraz i wydawcę.','WebSite'=>'Strona internetowa','Output WebSite schema on the front page and blog index'=>'Wypisz schemat WebSite na stronie głównej i na stronie bloga','Includes site name, url, and inLanguage.'=>'Zawiera nazwę witryny, URL i inLanguage.','Product'=>'Produkt','Output Product schema on WooCommerce product pages'=>'Wynik schematu Product na stronach produktów WooCommerce','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'Zawiera nazwę, opis, inLanguage, URL, obraz i ofertę z ceną, walutą i dostępnością. Cena i dostępność pochodzą z produktu w języku źródłowym (model zapasów dzielonych).','Currently emitting'=>'Obecnie emitowane','Article / WebPage — all singular posts and pages'=>'Artykuł / Strona internetowa — wszystkie pojedyncze posty i strony','WebSite — front page / blog index'=>'Strona główna / indeks bloga','Product — WooCommerce product pages'=>'Produkt — strony produktów WooCommerce','Nothing — all types disabled'=>'Nic — wszystkie typy wyłączone','Save Schema.org Settings'=>'Zapisz ustawienia Schema.org','Blog / Editorial'=>'Blog / Redakcja','Product / eCommerce'=>'Produkt / eCommerce','Landing / Short-form'=>'Strona docelowa / Krótka forma','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'Filtruj według języka i typu posta, przeglądaj treści i kliknij Analizuj na dowolnym elemencie, aby uruchomić audyt SEO oparty na regułach — długość tytułu, meta opis, liczba słów, struktura nagłówków, pokrycie alt obrazów i linki wewnętrzne.','Treat H2 as H1 equivalent'=>'Traktuj H2 jako odpowiednik H1','Enable when your theme renders the post title as an H2 instead of an H1 (common in some block themes). The analyser fetches the rendered page and, if it finds no H1 but does find an H2, it promotes the first H2 to H1 for scoring purposes.'=>'Włącz, gdy motyw renderuje tytuł jako H2 zamiast H1 (częste w niektórych motywach blokowych). Analizator pobiera renderowaną stronę i, jeśli nie znajdzie H1, ale znajdzie H2, promuje pierwsze H2 do H1 dla celów oceny.','Save analysis settings'=>'Zapisz ustawienia analizy','Per-Post Analysis'=>'Analiza dla każdego wpisu','Select a post and run a detailed SEO audit to see per-metric results and a score for that specific item.'=>'Wybierz wpis i uruchom szczegółowy audyt SEO, aby zobaczyć wyniki dla poszczególnych metryk i wynik dla tego konkretnego elementu.','Language'=>'Język','source'=>'źródło','All types'=>'Wszystkie typy','Load content'=>'Załaduj treść','Batch Analysis'=>'Analiza wsadowa','Run a full SEO audit across all published posts for one or all active languages. Scores are saved per post and reflected in the Language column badges in the post list.'=>'Przeprowadź pełny audyt SEO dla wszystkich opublikowanych wpisów dla jednego lub wszystkich aktywnych języków. Wyniki są zapisywane dla każdego wpisu i odzwierciedlają się w odznakach kolumny Język na liście wpisów.','WooCommerce system pages (Shop, Cart, Checkout, My Account) are excluded — their content is managed by WooCommerce and cannot be improved through SEO edits.'=>'Strony systemowe WooCommerce (Sklep, Koszyk, Realizacja zamówienia, Moje konto) są wyłączone — ich treść jest zarządzana przez WooCommerce i nie można jej poprawić przez edycję SEO.','Post type'=>'Typ wpisu','Default profile'=>'Domyślny profil','— Auto-detect —'=>'— Automatyczne wykrywanie —','Analyse all languages'=>'Analiza wszystkich języków','Auto-detect assigns: WooCommerce products → Product profile; the static front page → Landing profile; everything else → Blog profile. Choose a specific profile to override this for all posts.'=>'Automatyczne wykrywanie przypisuje: produkty WooCommerce → profil produktu; statyczna strona główna → profil landing; wszystko inne → profil bloga. Wybierz konkretny profil, aby to nadpisać dla wszystkich wpisów.','%d post'=>'%d wpis' . "\0" . '%d wpisów' . "\0" . '%d wpisów','Last run: %s ago'=>'Ostatnio uruchomione: %s temu','Never run'=>'Nigdy nie uruchamiaj','avg'=>'średnia','(partial)'=>'(częściowy)','Analyse'=>'Analiza','(no title) #%d'=>'(brak tytułu) #%d','Invalid post ID.'=>'Nieprawidłowy identyfikator posta.','Post not found or not published.'=>'Nie znaleziono lub nie opublikowano wpisu.','~%d min read'=>'~%d min czytania' . "\0" . '~%d min czytania' . "\0" . '~%d min czytania','No title set.'=>'Nie ustawiono tytułu.','Title is %1$d chars — may be truncated in SERPs (aim for under %2$d).'=>'Tytuł ma %1$d znaków — może być obcięty w wynikach wyszukiwania (dążyć do poniżej %2$d).','Title is only %d chars — aim for at least 10 characters.'=>'Tytuł ma tylko %d znaków — staraj się mieć co najmniej 10 znaków.','Single-word title (%d chars) — adding a second word improves clarity and keyword coverage.'=>'Tytuł jedno słowo (%d znaków) — dodanie drugiego słowa poprawia czytelność i pokrycie słów kluczowych.','%1$d chars, %2$d words — good title.'=>'%1$d znaków, %2$d słów — dobry tytuł.','Using LF AI meta description.'=>'Używanie meta opisu AI LF.','No LF meta description set — using excerpt/content.'=>'Nie ustawiono meta opisu LF — używany jest fragment treści.','No meta description found. Generate one via the AI meta description feature.'=>'Nie znaleziono meta opisu. Wygeneruj go za pomocą funkcji AI do tworzenia meta opisów.','%1$d chars — too short (aim for %2$d–%3$d). %4$s'=>'%1$d znaków — za krótko (dąż do %2$d–%3$d). %4$s','%1$d chars — likely truncated in SERPs (keep under %2$d). %3$s'=>'%1$d znaków — prawdopodobnie obcięte w wynikach wyszukiwania (zachowaj poniżej %2$d). %3$s','%1$d chars — good, slightly above the ideal %2$d but within the accepted %3$d-char range. %4$s'=>'%1$d znaków — dobry wynik, nieco powyżej idealnej wartości %2$d, ale w ramach akceptowalnego zakresu %3$d znaków. %4$s','%1$d chars — ideal length. %2$s'=>'%1$d znaków — idealna długość. %2$s','%1$d words — very thin content. Consider expanding to at least %2$d words.'=>'%1$d słów — bardzo mała zawartość. Rozważ rozszerzenie do co najmniej %2$d słów.','%1$d words — below recommended minimum of %2$d.'=>'%1$d słów — poniżej zalecanego minimum %2$d.','%d words.'=>'%d słów.','H2-as-H1 mode enabled — title counted as H1 equivalent. (Heading tags could not be detected from the rendered page; verify your theme outputs the title correctly.)'=>'Tryb H2 jako H1 włączony — tytuł liczony jako odpowiednik H1. (Tagi nagłówków nie mogły zostać wykryte na renderowanej stronie; sprawdź, czy Twój motyw poprawnie wyświetla tytuł.)','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'Nie znaleziono H1. Zazwyczaj tytuł posta jest H1 — sprawdź, czy Twój motyw go generuje.','%d H1 tags found — a page should have exactly one H1.'=>'Znaleziono %d tagów H1 — strona powinna mieć dokładnie jeden H1.','1 H1 ✓ — no H2, but %d H3 subheading(s) found (e.g. accordion/details headers). Structure is acceptable.'=>'1 H1 ✓ — brak H2, ale znaleziono %d podtytuł(i) H3 (np. nagłówki akordeonów/szczegółów). Struktura jest akceptowalna.','1 H1 ✓ — short content (%d paragraph(s)), subheadings not required.'=>'1 H1 ✓ — krótka treść (%d akapitów), podtytuły nie są wymagane.','1 H1 ✓ — no H2 subheadings (acceptable for this content type).'=>'1 H1 ✓ — brak podtytułów H2 (akceptowalne dla tego typu treści).','1 H1 ✓ — no H2 or H3 subheadings found. Adding H2s improves structure.'=>'1 H1 ✓ — nie znaleziono nagłówków H2 ani H3. Dodanie H2 poprawia strukturę.','1 H1 ✓, %1$d H2, %2$d H3.'=>'1 H1 ✓, %1$d H2, %2$d H3.','No images found in content.'=>'Nie znaleziono obrazów w treści.','%1$d of %2$d image(s) missing alt text.'=>'Brakujący tekst alternatywny dla %1$d z %2$d obrazów.','%d image(s), all have alt text.'=>'%d obrazów, wszystkie mają tekst alternatywny.','No links found. Internal links improve crawlability and user navigation.'=>'Nie znaleziono linków. Linki wewnętrzne poprawiają indeksowalność i nawigację użytkowników.','No links found.'=>'Nie znaleziono linków.','%d external link(s), no internal links. Add internal links to related content.'=>'%d zewnętrznych linków, brak wewnętrznych. Dodaj linki wewnętrzne do powiązanej treści.','%d external link(s), no internal links.'=>'%d zewnętrznych linków, brak linków wewnętrznych.','%1$d internal, %2$d external.'=>'%1$d wewnętrznych, %2$d zewnętrznych.','Post not found.'=>'Nie znaleziono wpisu.','No AI provider configured. Add an API key in Settings → API Keys.'=>'Brak skonfigurowanego dostawcy AI. Dodaj klucz API w Ustawienia → Klucze API.','No response from AI provider. Check your API key and try again.'=>'Brak odpowiedzi od dostawcy AI. Sprawdź klucz API i spróbuj ponownie.','AI returned an unexpected response format. Please try again.'=>'AI zwróciło nieoczekiwany format odpowiedzi. Spróbuj ponownie.','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'Lingua Forge generuje dedykowaną mapę witryny XML pod adresem /lf-sitemap.xml, która dodaje alternatywne linki językowe dla wszystkich Twoich przetłumaczonych treści. Ta mapa witryny uzupełnia mapę WordPressa i mapę wtyczek SEO — nie je zastępuje.','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'Mapa witryny WordPress listuje wszystkie Twoje adresy URL treści. Mapa LF informuje wyszukiwarki, jak wersje językowe odnoszą się do siebie za pomocą alternatyw XHTML:link hreflang. Prześlij obie do Google Search Console, aby uzyskać pełne pokrycie.','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'%s jest aktywne i generuje własną mapę witryny. Ta mapa jest oddzielna od mapy LF. Obie powinny być zgłoszone do Google Search Console: mapa witryny SEO wymienia Twoje treści; mapa LF dodaje wielojęzyczne linki alternatywne. Mapa LF jest automatycznie zgłaszana w robots.txt.','Sitemap settings saved.'=>'Ustawienia mapy witryny zapisane.','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'Pamięć podręczna mapy witryny wyczyszczona. Zostanie ona odtworzona przy następnej wizycie pod adresem URL mapy witryny.','Sitemap output'=>'Wynik mapy witryny','Generate the multilingual sitemap at /lf-sitemap.xml'=>'Wygeneruj wielojęzyczną mapę witryny pod /lf-sitemap.xml','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'Po włączeniu, URL mapy witryny jest automatycznie ogłaszany w robots.txt, a pamięć podręczna jest odświeżana po zapisaniu tłumaczonej treści.','Sitemap URL'=>'URL mapy witryny','Submit this URL to Google Search Console alongside your main sitemap.'=>'Prześlij ten URL do Google Search Console razem z główną mapą witryny.','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'Jeszcze nie wygenerowano. Mapa witryny jest tworzona przy pierwszej wizycie pod adresem URL mapy witryny i jest buforowana na 24 godziny.','✓ Active — %d URL entry with language alternates'=>'✓ Aktywne — %d wpisów URL z alternatywami językowymi' . "\0" . '✓ Aktywne — %d wpisów URL z alternatywami językowymi' . "\0" . '✓ Aktywne — %d wpisów URL z alternatywami językowymi','No translated content found. The sitemap will populate once posts have been translated.'=>'Nie znaleziono treści przetłumaczonych. Mapa witryny zostanie wypełniona po przetłumaczeniu postów.','Last generated: %s'=>'Ostatnia generacja: %s','Save Sitemap Settings'=>'Zapisz ustawienia mapy witryny','Flush Sitemap Cache'=>'Wyczyść pamięć podręczną mapy witryny','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'Wymusza ponowne wygenerowanie mapy witryny przy następnym żądaniu. Użyj po masowym imporcie lub ręcznym edytowaniu relacji tłumaczeń.','IndexNow'=>'IndexNow','IndexNow is an open protocol supported by Bing, Yandex, and other search engines. When a translated post is published or updated, Lingua Forge automatically notifies all participating engines in a single push — no polling, no waiting for the next robots.txt crawl.'=>'IndexNow to otwarty protokół obsługiwany przez Bing, Yandex i inne wyszukiwarki. Gdy opublikowany lub zaktualizowany jest przetłumaczony post, Lingua Forge automatycznie powiadamia wszystkie uczestniczące silniki w jednym pushu — bez pollingowania, bez oczekiwania na następne crawl robots.txt.','IndexNow replaces the deprecated Bing and Yandex sitemap-ping endpoints. Google discovers sitemaps via the robots.txt Sitemap: directive as before.'=>'IndexNow zastępuje wycofane punkty końcowe Bing i Yandex do pingowania map witryn. Google odkrywa mapy witryn za pomocą dyrektywy Sitemap w pliku robots.txt jak wcześniej.','✓ All URLs submitted to IndexNow successfully.'=>'✓ Wszystkie URL-e zgłoszone do IndexNow pomyślnie.','No translated URLs found to submit. Publish some translated posts first.'=>'Nie znaleziono przetłumaczonych URL-i do przesłania. Najpierw opublikuj kilka przetłumaczonych postów.','✗ IndexNow submission failed. Check that the key file is publicly reachable (see below) and try again.'=>'✗ Niepowodzenie zgłoszenia IndexNow. Sprawdź, czy plik klucza jest dostępny publicznie (patrz poniżej) i spróbuj ponownie.','Verification key'=>'Klucz weryfikacyjny','Key file served automatically at: %s'=>'Plik klucza jest automatycznie dostępny pod: %s','Key could not be generated. Check that the site has write access to WordPress options.'=>'Nie można wygenerować klucza. Sprawdź, czy witryna ma dostęp do zapisu w opcjach WordPress.','Key file status'=>'Status pliku klucza','✓ Key file is publicly reachable.'=>'✓ Plik klucza jest publicznie dostępny.','✗ Key file is not reachable.'=>'✗ Plik klucza nie jest dostępny.','IndexNow engines verify the key file before accepting submissions. If the file is not reachable, submissions will be rejected with a 403 error.'=>'Silniki IndexNow weryfikują plik klucza przed przyjęciem zgłoszeń. Jeśli plik nie jest dostępny, zgłoszenia zostaną odrzucone z błędem 403.','Common causes: full-page caching (clear it), a security plugin blocking .txt files, or a custom Nginx/Apache rule. The file is served by LF on every request — no physical file is written to disk.'=>'Przyczyny najczęstsze: pełne buforowanie strony (wyczyścić), wtyczka zabezpieczająca blokująca pliki .txt lub niestandardowa reguła Nginx/Apache. Plik jest serwowany przez LF przy każdym żądaniu — żaden fizyczny plik nie jest zapisywany na dysku.','Submit all URLs'=>'Prześlij wszystkie adresy URL','Submit all URLs via IndexNow'=>'Prześlij wszystkie URL-e przez IndexNow','Pushes every published, LF-managed URL to IndexNow in one batch. Automatic submission already runs on every publish/update — use this only after a bulk import or when setting up IndexNow for the first time.'=>'Wysyła wszystkie opublikowane URL-e zarządzane przez LF do IndexNow w jednym pakiecie. Automatyczne zgłoszenie działa przy każdym opublikowaniu/aktualizacji — użyj tego tylko po masowym imporcie lub przy pierwszym ustawianiu IndexNow.','Google does not participate in IndexNow. It discovers sitemaps via the robots.txt Sitemap: directive — which LF has already configured. Use Google Search Console to monitor indexing coverage.'=>'Google nie uczestniczy w IndexNow. Odkrywa mapy witryny za pośrednictwem dyrektywy Sitemap: w pliku robots.txt — którą LF już skonfigurował. Użyj Google Search Console, aby monitorować zasięg indeksowania.','Open Search Console →'=>'Otwórz Search Console →','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'robots.txt zaktualizowany z dyrektywą Sitemap.','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ Znaleziono fizyczny plik robots.txt. Obecna jest dyrektywa mapy witryny LF.','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'Na stronie istnieje fizyczny plik robots.txt. Wirtualny robots.txt WordPressa — i filtr Sitemap LF — są pomijane. Mapa witryny LF nie jest zgłaszana wyszukiwarkom.','Add Sitemap directive to robots.txt'=>'Dodaj dyrektywę Sitemap do robots.txt','Appends the following line to your existing robots.txt: %s'=>'Dodaje następującą linię do istniejącego robots.txt: %s','DISALLOW_FILE_MODS is set.'=>'Ustawiono DISALLOW_FILE_MODS.','Add the following line to your robots.txt manually:'=>'Dodaj następującą linię do robots.txt ręcznie:','View current robots.txt'=>'Zobacz aktualny robots.txt','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'Nie znaleziono fizycznego pliku robots.txt. WordPress generuje go wirtualnie, a dyrektywa Sitemap LF jest automatycznie dołączona.','The following directive is active in your virtual robots.txt:'=>'Następująca dyrektywa jest aktywna w Twoim wirtualnym pliku robots.txt:','File modifications are disabled (DISALLOW_FILE_MODS).'=>'Modyfikacje plików są wyłączone (DISALLOW_FILE_MODS).','Could not write to robots.txt. Check file permissions.'=>'Nie można zapisać do robots.txt. Sprawdź uprawnienia pliku.','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'Lingua Forge rozszerza blok ikon społecznościowych WordPressa o dynamiczne adresy URL do udostępniania. Ustaw dowolny link ikony na wartość "share:", a LF przepisze go na poprawny URL udostępniania lub akcję JavaScript podczas renderowania — bez konieczności używania własnego kodu lub wtyczek zewnętrznych.','Social Share settings saved.'=>'Ustawienia udostępniania społecznościowego zapisane.','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'Wtyczka mu lf-social-share jest aktywna. Wbudowany mechanizm Social Share Lingua Forge jest nieaktywny — wtyczka mu obsługuje przepisywanie URL-i udostępniania i działania JS.','Social Share'=>'Udostępnianie społecznościowe','Enable Social Share URL rewriting for Social Icons blocks'=>'Włącz przepisywanie URL społecznego udostępniania dla bloków ikon społecznych','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'Wyłączone, ponieważ mu-plugin lf-social-share już zapewnia tę funkcję.','Save Social Share Settings'=>'Zapisz ustawienia udostępniania społecznościowego','How to use'=>'Jak używać','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'W edytorze bloków dodaj blok ikon społecznych. Dla każdej ikony otwórz ustawienia linku i wpisz jedną z wartości "share:" poniżej jako URL. Na stronie LF zastępuje to poprawnym URL udostępniania dla bieżącej strony.','External share services'=>'Zewnętrzne usługi udostępniania','URL to enter'=>'URL do wpisania','Action'=>'Akcja','Share on Facebook'=>'Udostępnij na Facebooku','Post on X / Twitter'=>'Wpis na X / Twitter','Share on LinkedIn'=>'Udostępnij na LinkedIn','Send via WhatsApp'=>'Wyślij przez WhatsApp','Send via Telegram'=>'Wyślij przez Telegram','Submit to Reddit'=>'Prześlij do Reddit','Pin on Pinterest'=>'Przypnij na Pinterest','Share on Mastodon'=>'Udostępnij na Mastodon','Share via email (mailto:)'=>'Udostępnij przez e-mail (mailto:)','JavaScript-powered actions'=>'Akcje oparte na JavaScript','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'Skopiuj bieżący URL do schowka. Pokaże się powiadomienie "Link skopiowany" po sukcesie.','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'Otwórz natywny arkusz udostępniania w przeglądarce (iOS, Android, niektóre desktopy). W przypadku braku obsługi, kopiuje do schowka.','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'Użyj natywnego udostępniania, gdy jest dostępne; w razie potrzeby skopiuj do schowka. Zalecany domyślny dla przycisków "Udostępnij".','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'URL udostępniania zawsze odzwierciedla bieżącą stronę — nie jest potrzebne ręczne wpisywanie URL. filtr linguaforge_social_share_url pozwala nadpisać rozwiązaną URL dla dowolnej usługi.','Configuration issue: WP site language has no content on this site'=>'Problem z konfiguracją: język witryny WP nie ma zawartości na tej stronie','The WordPress site language (%1$s) maps to the language code "%2$s", but no posts on this site are tagged _lf_lang=%2$s. This causes WooCommerce product queries to return zero results, product images to fail, and all language-filtered content queries to break.'=>'Język witryny WordPress (%1$s) mapuje się na kod języka „%2$s", ale żaden post na tej witrynie nie jest oznaczony tagiem _lf_lang=%2$s. Powoduje to, że zapytania produktów WooCommerce zwracają zero wyników, obrazy produktów się nie ładują, a wszystkie zapytania dotyczące zawartości filtrowanej według języka się psują.','Fix: go to'=>'Napraw: przejdź do','Settings → General → Site Language'=>'Ustawienia → Ogólne → Język witryny','and set it to one of your actual content languages (e.g. %s).'=>'i ustaw go na jeden z twoich rzeczywistych języków treści (np. %s).','Environment'=>'Środowisko','Lingua Forge version'=>'Wersja Lingua Forge','WordPress version'=>'Wersja WordPressa','PHP version'=>'Wersja PHP','Active theme'=>'Aktywny motyw','(FSE / block theme)'=>'(FSE / motyw blokowy)','(classic theme)'=>'(klasyczny motyw)','URL structure'=>'Struktura URL','Subdomain (de.example.com)'=>'Subdomena (de.example.com)','Path prefix (/de/)'=>'Przedrostek ścieżki (/de/)','WP instance language'=>'Język instancji WP','not a content language — see notice above'=>'nie jest językiem treści — zobacz powiadomienie powyżej','Primary content language'=>'Główny język treści','Active languages'=>'Aktywne języki','PHP max_execution_time'=>'Maksymalny czas wykonywania PHP','No PHP limit'=>'Brak limitu PHP','(server/FPM timeout still applies)'=>'(wciąż obowiązuje limit czasu serwera/FPM)','AI translation and batch analysis may time out. Recommend 120s or more.'=>'Tłumaczenie AI i analiza wsadowa mogą się wyłączyć. Zalecane 120 sekund lub więcej.','PHP memory_limit'=>'Limit pamięci PHP','AI Configuration'=>'Konfiguracja AI','(active)'=>'(aktywny)','Configured'=>'Skonfigurowano','No key'=>'Brak klucza','— AI features are disabled.'=>'— Funkcje AI są wyłączone.','Add key →'=>'Dodaj klucz →','Light model'=>'Lekki model','Quality model'=>'Model jakości','Active preset'=>'Aktywny preset','Daily quota'=>'Dzienne limity','Unlimited'=>'Nieograniczony','requests / day'=>'żądania / dzień','Permalink Structure'=>'Struktura permalinków','Permalink structure is compatible with Lingua Forge path routing.'=>'Struktura permalinków jest kompatybilna z routingiem ścieżek Lingua Forge.','Plain permalinks are not supported.'=>'Proste permalinków nie są obsługiwane.','Path routing requires a post-name based permalink structure. Change it in'=>'Routing ścieżki wymaga struktury permalinków opartej na nazwie wpisu. Zmień to w','Settings → Permalinks'=>'Ustawienia → Permalinki','Numeric permalink structure is not supported.'=>'Struktura permalinków numerycznych nie jest obsługiwana.','Switch to a post-name based structure in'=>'Przełącz na strukturę opartą na nazwie wpisu w','SEO Plugins'=>'Wtyczki SEO','No third-party SEO plugins detected. Lingua Forge handles all multilingual SEO output.'=>'Nie wykryto wtyczek SEO innych firm. Lingua Forge obsługuje wszystkie wielojęzyczne wyjścia SEO.','Active: %s.'=>'Aktywny: %s.','See Settings → SEO → Compatibility for the full per-feature behaviour table.'=>'Zobacz Ustawienia → SEO → Kompatybilność, aby uzyskać pełną tabelę zachowań według funkcji.','WooCommerce'=>'WooCommerce','WooCommerce is not active.'=>'WooCommerce nie jest aktywne.','Shop'=>'Sklep','Cart'=>'Koszyk','Checkout'=>'Kasa','My Account'=>'Moje konto','WooCommerce version'=>'Wersja WooCommerce','Order storage'=>'Przechowywanie zamówień','High-Performance Order Storage (HPOS)'=>'Wysokowydajne przechowywanie zamówień (HPOS)','Custom tables — LF post-meta filters do not affect orders.'=>'Niestandardowe tabele — filtry LF post-meta nie wpływają na zamówienia.','Shared / compatibility mode'=>'Tryb współdzielony / kompatybilności','HPOS + CPT synced — transitional; LF post-meta filters apply to CPT copy.'=>'HPOS + CPT zsynchronizowane — przejściowo; filtry LF post-meta mają zastosowanie do kopii CPT.','Legacy post-based (CPT)'=>'Legacy post-based (CPT)','Orders in wp_posts — ensure shop_order is excluded from LF routing.'=>'Zamówienia w wp_posts — upewnij się, że shop_order jest wykluczony z routingu LF.','WcPageBridge active'=>'Włączony WcPageBridge','Yes'=>'Tak','No — WooCommerce integration class not loaded'=>'Brak — klasa integracji WooCommerce nie załadowana','WooCommerce page translations'=>'Tłumaczenia stron WooCommerce','No secondary languages configured.'=>'Nie skonfigurowano języków dodatkowych.','Active Plugins'=>'Aktywne wtyczki','No active plugins detected.'=>'Nie wykryto aktywnych wtyczek.','Version'=>'Wersja','_lf_lang Coverage'=>'Pokrycie _lf_lang','Posts without _lf_lang are invisible to every Lingua Forge language filter. This can happen when content is imported or created before the plugin was activated.'=>'Wpisy bez _lf_lang są niewidoczne dla każdego filtra językowego Lingua Forge. Może się tak dziać podczas importu treści lub tworzenia przed aktywacją wtyczki.','All published posts have a _lf_lang value. No gaps detected.'=>'Wszystkie opublikowane wpisy mają wartość _lf_lang. Nie wykryto luk.','Missing'=>'Brakujący','Exclude this post type from language routing — its posts will no longer appear here or receive _lf_lang. This cannot be undone automatically.'=>'Wyklucz ten typ posta z routingu językowego — jego posty nie będą już wyświetlane tutaj ani nie będą otrzymywać _lf_lang. Nie można tego cofnąć automatycznie.','Exclude from routing'=>'Wyklucz z routingu','excluded from routing'=>'wykluczony z routingu','Destructive action — read before proceeding'=>'Działanie destrukcyjne — przeczytaj przed kontynuacją','Repair tags every routable post listed above with _lf_lang = %s. Posts in routing-excluded post types are not touched. Only run this after importing content or on initial activation — do not use as a bulk language-reassignment tool.'=>'Napraw tagi każdego postu możliwego do routowania wymienionego powyżej z _lf_lang = %s. Posty w wykluczonych typach postów nie są modyfikowane. Uruchom to tylko po imporcie treści lub przy pierwszym uruchomieniu — nie używaj jako narzędzia do masowego przypisywania języków.','Repair — assign _lf_lang = %s to all routable posts above'=>'Napraw — przypisz _lf_lang = %s wszystkim postom możliwym do routowania powyżej','Rewrite Rules'=>'Reguły przepisywania','LF-owned entries currently registered in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts. Copy these when filing a bug report.'=>'Pozycje własności LF obecnie zarejestrowane w $wp_rewrite->extra_rules_top. Przydatne do diagnozowania 404 lub konfliktów routingu. Skopiuj je podczas zgłaszania błędu.','%d rule registered'=>'Zarejestrowano %d regułę' . "\0" . 'Zarejestrowano %d reguły' . "\0" . 'Zarejestrowano %d reguły','No LF rewrite rules found. Flush permalinks if this is unexpected.'=>'Nie znaleziono reguł przepisywania LF. Odśwież permalink, jeśli to nieoczekiwane.','Debug Info'=>'Informacje debugowania','Copy and paste into a GitHub issue or support request.'=>'Skopiuj i wklej do zgłoszenia na GitHub lub prośby o wsparcie.','Copy system info'=>'Skopiuj informacje o systemie','Copied!'=>'Skopiowano!','Repairing…'=>'Naprawa…','Repair failed.'=>'Naprawa nie powiodła się.','Network error.'=>'Błąd sieci.','Exclude this post type from language routing? Its posts will no longer appear in this list or receive _lf_lang. You can reverse this in Settings → Router → Query Filter Exclusions.'=>'Wyklucz ten typ posta z routingu językowego? Jego posty nie będą już wyświetlane na tej liście ani nie będą otrzymywać _lf_lang. Możesz to odwrócić w Ustawieniach → Router → Wykluczenia filtra zapytań.','Excluding…'=>'Wykluczanie…','Failed to save exclusion.'=>'Nie udało się zapisać wykluczenia.','%1$d post tagged with _lf_lang = %2$s.'=>'%1$d opublikowanych wpisów oznaczonych _lf_lang = %2$s.' . "\0" . '%1$d opublikowanych wpisów oznaczonych _lf_lang = %2$s.' . "\0" . '%1$d opublikowanych wpisów oznaczonych _lf_lang = %2$s.','Uninstall Behaviour'=>'Odinstaluj zachowanie','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Kontroluje, co się dzieje, gdy administrator usuwa wtyczkę z Plugins → Installed Plugins → Delete. Ustawienia wtyczki i pamięć podręczna AI są zawsze usuwane. Przydziały językowe i relacje tłumaczeń są domyślnie zachowywane, więc przypadkowe odinstalowanie lub reinstalacja mogą kontynuować tam, gdzie zostały przerwane.','Uninstall setting saved.'=>'Ustawienie odinstalowania zapisane.','Delete content data on uninstall'=>'Usuń dane zawartości podczas odinstalowania','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Usuń również przypisania językowe, relacje tłumaczeń, meta opisy, glosariusz i pamięć tłumaczeń podczas odinstalowania wtyczki.','Warning:'=>'Ostrzeżenie:','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Jeśli zaznaczysz, odinstalowanie wtyczki trwale usunie wszystkie przypisania językowe, relacje tłumaczeń, meta opisy, ustawienia na stronie, glosariusz AI i pamięć tłumaczeń dla każdego posta na tej stronie. Nie można tego cofnąć. Odznacz, jeśli chcesz całkowicie usunąć obsługę wielojęzyczności ze strony.','Save Uninstall Setting'=>'Zapisz ustawienie odinstalowania','Today'=>'Dziś','Last 7 days'=>'Ostatnie 7 dni','Last 30 days'=>'Ostatnie 30 dni','All time'=>'Wszystko','AI Usage'=>'Użycie AI','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'Zużycie tokenów zsumowane według funkcji, dostawcy i modelu. Rejestrowane przy każdym udanym wywołaniu AI; pingi Test Connection są wykluczone, aby nie zniekształcać sum.','Check your account, billing, or remaining credits directly on the provider console:'=>'Sprawdź swoje konto, rozliczenia lub pozostałe kredyty bezpośrednio w konsoli dostawcy:','Anthropic Console'=>'Konsola Anthropic','OpenAI Platform'=>'Platforma OpenAI','Google AI Studio'=>'Google AI Studio','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Jeszcze nie zarejestrowano użycia AI. Gdy edytor wykona tłumaczenie, wygeneruje opis meta lub skorzysta z innej funkcji AI, sumy pojawią się tutaj.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Nie zarejestrowano użycia AI w wybranym oknie (%s). Wybierz szerszy zakres powyżej.','Provider'=>'Dostawca','Model'=>'Model','Requests'=>'Żądania','Input tokens'=>'Tokeny wejściowe','Output tokens'=>'Tokeny wyjściowe','Total tokens'=>'Razem tokenów','Total'=>'Razem','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'Lingua Forge dodaje specyficzne dla WooCommerce właściwości Open Graph do stron produktów, aby udostępnianie URL produktu na Facebooku, Pinterest i podobnych platformach wyświetlało poprawny typ produktu, cenę i dostępność.','WooCommerce SEO settings saved.'=>'Ustawienia SEO WooCommerce zapisane.','Product Open Graph'=>'Open Graph produktu','Add WooCommerce product tags to Open Graph output'=>'Dodaj tagi produktów WooCommerce do wyjścia Open Graph','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'Po włączeniu, Lingua Forge generuje następujące dodatkowe meta tagi na stronach produktów: og:type=product, og:price:amount, og:price:currency, og:availability oraz ich odpowiedniki w przestrzeni nazw product: używane przez Facebook Catalog.','Tags emitted'=>'Emitowane tagi','Tag'=>'Tag','Value source'=>'Źródło wartości','"product" (replaces "article")'=>'"produkt" (zastępuje "artykuł")','WooCommerce product price'=>'Cena produktu WooCommerce','WooCommerce store currency'=>'Waluta sklepu WooCommerce','instock / oos / pending from WC stock status'=>'w magazynie / brak w magazynie / oczekujące z statusu magazynowego WC','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'Cena i dostępność zawsze odzwierciedlają produkt w języku źródłowym (model wspólnego stanu magazynowego). Tagów używa się tylko wtedy, gdy moduł Open Graph LF jest ustawiony na "Full" lub "Auto" i nie wykryto konfliktującej wtyczki SEO.','Save WooCommerce SEO Settings'=>'Zapisz ustawienia SEO WooCommerce','AI Provider'=>'Dostawca AI','AI Usage & Cache'=>'Użycie AI i pamięć podręczna','API Keys'=>'Klucze API','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Klucze są szyfrowane za pomocą AES-256-CBC przed zapisaniem w bazie danych WordPress. Sekret szyfrowania pochodzi z Twoich soli uwierzytelniania WordPress (wp-config.php), więc klucze w formacie tekstowym nigdy nie trafiają do bazy danych.','API credentials are managed by WordPress in %s. No key is stored by Lingua Forge.'=>'Dane uwierzytelniające API są zarządzane przez WordPress w %s. Żaden klucz nie jest przechowywany przez Lingua Forge.','Settings → Connectors'=>'Ustawienia → Łączniki','API Key'=>'Klucz API','Paste your API key…'=>'Wklej swój klucz API…','✓ Configured'=>'✓ Skonfigurowano','✗ Not configured'=>'✗ Nie skonfigurowano','Test connection'=>'Testuj połączenie','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Pozostaw puste, aby zachować istniejący klucz. Wprowadź nową wartość, aby go zastąpić.','Remove stored key'=>'Usuń zapisany klucz','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Ten klucz jest obecnie dostarczany przez serwer %s i nie można go usunąć tutaj. Wprowadź nowy klucz powyżej, aby nadpisać go wartością z bazy danych.','environment variable'=>'zmienna środowiskowa','PHP constant'=>'stała PHP','Alternative (server-side):'=>'Alternatywnie (po stronie serwera):','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Możesz również definiować klucze jako stałe lub zmienne środowiskowe (np. w wp-config.php). Te źródła są automatycznie używane jako zapasowe, gdy nie ma zapisanej klucza w bazie danych.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Aby użyć własnego sekretu szyfrowania (zamiast wyprowadzonej wartości wp_salt), dodaj to do wp-config.php:','Unknown provider.'=>'Nieznany dostawca.','No API key configured for this provider.'=>'Dla tego dostawcy nie skonfigurowano klucza API.','Could not instantiate the provider.'=>'Nie można utworzyć instancji dostawcy.','Provider returned no response. Check the WordPress error log for details.'=>'Dostawca nie zwrócił odpowiedzi. Sprawdź dziennik błędów WordPressa po szczegóły.','Enter a model identifier to test.'=>'Wpisz identyfikator modelu do przetestowania.','No published post or page found to test with — publish some content first, or try Quick Translate directly.'=>'Nie znaleziono opublikowanego wpisu lub strony do przetestowania — opublikuj najpierw zawartość lub spróbuj Szybkiego tłumaczenia bezpośrednio.','(untitled)'=>'(bez tytułu)','Prompt template not found.'=>'Szablon polecenia nie znaleziony.','Translation failed. Please try again.'=>'Tłumaczenie nie powiodło się. Spróbuj ponownie.','The sample post has no visible text content to translate.'=>'Przykładowy wpis nie zawiera widocznej treści tekstowej do tłumaczenia.','Chunk prompt template not found.'=>'Szablon polecenia fragmentu nie znaleziony.','Model returned no response. Check the WordPress error log for details.'=>'Model nie zwrócił odpowiedzi. Sprawdź dziennik błędów WordPress, aby uzyskać szczegóły.','Behavior'=>'Zachowanie','Block Editor'=>'Edytor bloków','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge domyślnie ogranicza dwie funkcje Gutenberga, aby zachować spójne zachowanie redakcyjne w różnych językach. Zaznacz tutaj, gdy potrzebujesz pełnych możliwości Gutenberga / FSE.','Block locking'=>'Blokada','Allow editors to lock individual blocks'=>'Zezwól redaktorom na blokowanie poszczególnych bloków','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Ponownie włącza canLockBlocks Gutenberga. Przydatne dla szablonów redakcyjnych, które muszą zapobiegać przesuwaniu lub usuwaniu określonych bloków.','Template mode'=>'Tryb szablonu','Allow Gutenberg template-editing mode on post screens'=>'Zezwól na tryb edycji szablonów Gutenberga na ekranach wpisów','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Ponownie włącza supportsTemplateMode. Kluczowe dla pełnych przepływów pracy edycji całej strony, gdzie celowo nadpisuje się szablony na poziomie wpisu.','Compliance Preset'=>'Predefiniowany ustawienie zgodności','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Tryb ścisłego zachowania dla treści prawnych, regulacyjnych, medycznych lub technicznych. Gdy jest włączony, każda funkcja AI używa niskiej temperatury próbkowania i dodaje poniższy dodatek do swojego promptu systemowego — terminologia, numery artykułów, jednostki, nazwy marek i język regulacyjny są zachowywane dokładnie, a nie parafrazowane.','Global AI preset'=>'Globalny preset AI','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, na funkcję','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Ustawia domyślne zachowanie AI dla wszystkich funkcji w całej witrynie. Poszczególne wpisy mogą to nadpisać dla tłumaczeń i generowania treści za pomocą meta boxa Lingua Forge.','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Standard używa własnej dostrojonej temperatury dla każdej funkcji: Tłumaczenie T=0.2 (precyzyjne), Szybkie tłumaczenie T=0.4, Generator treści T=0.6 (kreatywne). Pozostałe preset\'y stosują jedną stałą temperaturę dla wszystkich funkcji.','Technical / Scientific instructions'=>'Instrukcje techniczne / naukowe','Legal / Compliance instructions'=>'Instrukcje prawne / zgodności','Creative / Marketing instructions'=>'Instrukcje kreatywne / marketingowe','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Pozostaw puste, aby użyć wbudowanego domyślnego ustawienia. Wyczyszczenie zapisanej nadpisanej wartości przywraca domyślną wartość przy następnym zapisie.','View built-in default'=>'Wyświetl wbudowany domyślny','Automatic Translation Backfill'=>'Automatyczne uzupełnianie tłumaczeń','Periodically scans for posts missing a translation in an active language and queues an AI translation for each gap found — the same recovery you can already trigger by hand via "Translate missing" or the WP-CLI missing_translations/fill_translations commands, run automatically once an hour instead.'=>'Okresowo skanuje posty, którym brakuje tłumaczenia w aktywnym języku, i dodaje do kolejki AI tłumaczenie dla każdej luki — ta sama funkcja odzyskiwania, którą możesz uruchomić ręcznie za pomocą przycisku "Przetłumacz brakujące" lub poleceń WP-CLI missing_translations/fill_translations, ale uruchamiana automatycznie raz na godzinę.','Automatic backfill'=>'Automatyczne uzupełnianie','Automatically translate posts missing a language version'=>'Automatycznie tłumacz posty brakujące w wersji w danym języku','Off by default. This feature makes AI provider requests — and spends the associated API cost — automatically and in the background, with no per-request confirmation, for every published post found without a translation in an active language. Turn this on only if you want every content gap translated unattended; otherwise use "Translate missing" or the WP-CLI commands to translate on your own schedule.'=>'Domyślnie wyłączone. Ta funkcja powoduje automatyczne żądania do dostawcy AI — i powoduje dodatkowe koszty API — w tle bez potwierdzenia dla każdego żądania, dla każdego opublikowanego postu bez tłumaczenia w aktywnym języku. Włącz to tylko wtedy, gdy chcesz, aby wszystkie luki w treści były tłumaczone bezobsługowo; w przeciwnym razie użyj "Przetłumacz brakujące" lub poleceń WP-CLI, aby tłumaczyć według swojego harmonogramu.','WooCommerce products and variations are never included, regardless of this setting. An integration can also block specific post types via the linguaforge_cpt_create_allowed filter.'=>'Produkty WooCommerce i wariacje nigdy nie są uwzględniane, niezależnie od tego ustawienia. Integracja może również zablokować określone typy postów za pośrednictwem filtra linguaforge_cpt_create_allowed.','The "Sync" button in the post list Lang column retranslates a post out into every other language, including the primary/source post when it\'s run from a translation. That back-translation direction is restricted by default for every post type. (WooCommerce products and variations have their own separate setting below — this one does not affect them.)'=>'Przycisk "Sync" w kolumnie Lang listy postów ponownie tłumaczy post we wszystkie inne języki, w tym główny/źródłowy post, gdy uruchomiony jest z tłumaczenia. Kierunek tłumaczenia zwrotnego jest domyślnie ograniczony dla każdego typu postu. (Produkty WooCommerce i wariacje mają własne oddzielne ustawienie poniżej — to ustawienie ich nie dotyczy.)','Secondary-language Sync'=>'Sync drugorzędnego języka','Allow "Sync" on a translated post to overwrite the primary post'=>'Zezwól na "Sync" dla przetłumaczonego postu, aby zastąpić post główny','Off by default: clicking "Sync" on a translation is blocked from overwriting the primary post. Syncing FROM the primary post to every translation is always allowed regardless of this setting. Turn this on only if you intentionally want a translation to be able to become the new source content.'=>'Domyślnie wyłączone: kliknięcie "Sync" na tłumaczeniu jest zablokowane przed zastąpieniem postu głównego. Synchronizacja Z postu głównego do każdego tłumaczenia jest zawsze dozwolona, niezależnie od tego ustawienia. Włącz to tylko wtedy, gdy celowo chcesz, aby tłumaczenie mogło stać się nową zawartością źródłową.','The primary-language product is WooCommerce\'s operational source of truth for price, SKU, and stock, which are always served from it regardless of which language a shopper is viewing. This is a separate, independent setting from the general "Sync" restriction above — enabling one does not enable the other.'=>'Główny produkt w języku pierwotnym jest operacyjnym źródłem prawdy WooCommerce dla ceny, SKU i stanu magazynu, które są zawsze serwowane z niego, niezależnie od tego, który język klient przegląda. To jest oddzielne, niezależne ustawienie od ogólnego ograniczenia "Sync" powyżej — włączenie jednego nie włącza drugiego.','Allow "Sync" on a translated product to overwrite the primary product'=>'Zezwól na "Sync" dla przetłumaczonego produktu, aby zastąpić produkt główny','Off by default: clicking "Sync" on a translated WooCommerce product is blocked, since it would back-translate onto the primary product\'s title, description, and excerpt. Syncing FROM the primary product to every translation is always allowed regardless of this setting. Turn this on only if you intentionally want a translation to be able to become the new source content.'=>'Domyślnie wyłączone: kliknięcie "Sync" na przetłumaczonym produkcie WooCommerce jest zablokowane, ponieważ mogłoby to spowodować tłumaczenie zwrotne do tytułu, opisu i fragmentu głównego produktu. Synchronizacja Z głównego produktu do każdego tłumaczenia jest zawsze dozwolona, niezależnie od tego ustawienia. Włącz to tylko wtedy, gdy celowo chcesz, aby tłumaczenie mogło stać się nową zawartością źródłową.','General'=>'Ogólne','Light'=>'Lekki','Meta Description, Excerpt Generator, quick translate'=>'Meta opis, generator streszczeń, szybkie tłumaczenie','Quality'=>'Jakość','Full-page Translation, Content Generator (mid-tier models are fully sufficient)'=>'Tłumaczenie pełnej strony, Generator treści (modele średniego poziomu są w pełni wystarczające)','Active Provider'=>'Aktywny dostawca','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Obecnie dziedziczone z constanty %s. Wybranie wartości tutaj nadpisze to.','WordPress AI Client — requirements:'=>'Klient AI WordPress — wymagania:','Full-page translation uses JSON-schema-constrained output. This requires a connector plugin to be installed and active (not just an API key saved in Settings → Connectors). If translation fails, check the PHP error log for the specific error, or switch to a built-in provider.'=>'Tłumaczenie pełnej strony korzysta z wyjścia ograniczonego schematem JSON. Wymaga to zainstalowania i aktywacji wtyczki łącznika (nie tylko zapisania klucza API w Ustawieniach → Łączniki). Jeśli tłumaczenie się nie powodzi, sprawdź dziennik błędów PHP pod kątem konkretnego błędu lub przełącz się na wbudowanego dostawcę.','Manage your account, review usage, or top up credits:'=>'Zarządzaj swoim kontem, przeglądaj użycie lub doładuj kredyty:','WordPress Connectors'=>'Łączniki WordPress','Models'=>'Modele','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Funkcje są pogrupowane w dwie warstwy. Wprowadź dokładny identyfikator modelu dla każdej warstwy i dostawcy. Pozostaw pole puste, aby użyć wbudowanego domyślnego (pokazanego jako placeholder). Tylko modele aktywnego dostawcy są wywoływane podczas działania — skonfiguruj pozostałe wcześniej, jeśli planujesz zmianę.','Start typing in any field to see model suggestions, or use the reference table below. Light and mid-tier Quality models (Haiku, GPT-4o mini, Gemini Flash) are fully sufficient for translation and content generation — flagship "max" models add cost with minimal quality gain for structured text.'=>'Rozpocznij wpisywanie w dowolnym polu, aby zobaczyć sugestie modelu, lub skorzystaj z tabeli odniesienia poniżej. Modele jakości light i mid-tier (Haiku, GPT-4o mini, Gemini Flash) są w pełni wystarczające do tłumaczenia i generowania treści — flagowe modele "max" zwiększają koszty przy minimalnej poprawie jakości dla tekstu strukturalnego.','active'=>'aktywne','Model selection is managed by WordPress in %s — no model identifier is stored by Lingua Forge for this provider.'=>'Wybór modelu jest zarządzany przez WordPress w %s — Lingua Forge nie przechowuje identyfikatora modelu dla tego dostawcy.','overridden'=>'nadpisane','Translates a short sample of your most recent published post with this exact model — a real, billed API call.'=>'Tłumaczy krótką próbkę najnowszego opublikowanego postu z tym dokładnym modelem — rzeczywiste, rozliczane połączenie API.','Test model'=>'Test modelu','Tip: to reset a model to the built-in default, clear the field and save.'=>'Wskazówka: aby zresetować model do wbudowanego domyślnego, wyczyść pole i zapisz.','Available models reference'=>'Odwołanie do dostępnych modeli','Model ID'=>'ID modelu','Name'=>'Nazwa','Tier'=>'Poziom','Notes'=>'Uwagi','This catalog is updated with each Lingua Forge release. Testing a connection in the API Keys tab also fetches the live model list from the provider and refreshes the suggestions above.'=>'Ten katalog jest aktualizowany przy każdej wersji Lingua Forge. Testowanie połączenia w zakładce Klucze API również pobiera listę modeli na żywo od dostawcy i odświeża powyższe sugestie.','Glossary'=>'Słownik','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Tablica terminologii zarządzana przez użytkownika dla pary językowej. Wpisy są dodawane do promptu systemu tłumaczeń, aby AI używało preferowanych terminów konsekwentnie — kluczowe dla słownictwa dziedzinowego ("kWp", "PPA", "punkt połączenia"), nazw marek, które nie mogą być tłumaczone, oraz ustandaryzowanej frazeologii regulacyjnej. Oba pola językowe są opcjonalne: pozostaw "Język źródłowy" pusty, aby zastosować wpis niezależnie od języka, z którego tłumaczysz; pozostaw "Język docelowy" pusty, aby zastosować go do wszystkich języków docelowych naraz.','Glossary entry added.'=>'Wpis słownika dodany.','Glossary entry removed.'=>'Wpis słownika usunięty.','Could not add entry: source term and target term are required.'=>'Nie można dodać wpisu: wymagany jest termin źródłowy i termin docelowy.','Could not save the glossary entry.'=>'Nie można zapisać wpisu słownika.','Source language'=>'Język źródłowy','— Any —'=>'— Dowolny —','Target language'=>'Język docelowy','— Any target —'=>'— Dowolny język docelowy —','Filter'=>'Filtr','Reset'=>'Resetuj','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Brak wpisów słownika pasujących do obecnego filtra. Wyczyść filtr, aby zobaczyć wszystkie wpisy, lub dodaj nowy wpis poniżej.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Brak jeszcze wpisów słownika. Dodaj jeden poniżej, aby zacząć egzekwować terminologię w tłumaczeniach.','Source term'=>'Termin źródłowy','Target term'=>'Termin docelowy','Source lang'=>'Język źródłowy','Target lang'=>'Język docelowy','any'=>'dowolny','Delete this glossary entry?'=>'Czy chcesz usunąć ten wpis słownika?','Add new entry'=>'Dodaj nowy wpis','The phrase as it appears in the source text.'=>'Fraza tak jak pojawia się w tekście źródłowym.','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Jak powinna wyglądać w tłumaczeniu. Wpisz tę samą wartość co termin źródłowy, aby nakazać AI zachować ją dosłownie.','— Any source language —'=>'— Dowolny język źródłowy —','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Pozostaw puste dla nazw marek i terminów niezależnych od języka, które mają być egzekwowane bez względu na język tłumaczenia.','— Any target language —'=>'— Dowolny język docelowy —','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Pozostaw puste, aby zastosować tę pozycję do wszystkich języków docelowych — idealne dla nazw marek, skrótów i terminów, które muszą być zachowane dosłownie w każdym tłumaczeniu.','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Opcjonalny kontekst dla redaktorów (np. "ASIC = układ scalony specjalistyczny; zachować w języku angielskim w kontekstach technicznych").','Add entry'=>'Dodaj wpis','Limits'=>'Limity','Authors and above (edit_published_posts)'=>'Autorzy i wyżej (edytuj_opublikowane_posty)','Contributors and above — default (edit_posts)'=>'Współtwórcy i wyżej — domyślnie (edytuj_posty)','Editors and above (edit_others_posts)'=>'Redaktorzy i wyżej (edytuj_inne_posty)','Administrators only (manage_options)'=>'Tylko administratorzy (zarządzaj_opcjami)','AI Limits & Security'=>'Limity i bezpieczeństwo AI','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Ogranicz ilość korzystania z AI na stronie i ogranicz role użytkowników, które mogą wywołać płatne wywołania AI. Nakłada się na limit na poziomie użytkownika (30 żądań / minuta, na stałe), który już chroni przed niekontrolowanymi pętlami pojedynczego użytkownika.','Daily request limit'=>'Dzienny limit żądań','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Ogólny limit AI na stronie na UTC dzień (liczy zarówno tłumaczenia w Toolbar, jak i rewizje bloków). Licznik resetuje się o północy UTC. Ustaw na 0, aby wyłączyć limit.','Minimum role'=>'Minimalna rola','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Najniższa zdolność WordPress do wywoływania funkcji AI. Ograniczenie tego na stronach z wieloma autorami zapobiega uruchamianiu płatnych wywołań AI przez Współtwórców lub konta próbne. Nadpisz per funkcja za pomocą filtra linguaforge_required_capability.','Translation Limits'=>'Limity tłumaczeń','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Kontroluj, ile treści jest wysyłanych do AI i jak duża może być odpowiedź. Pozostaw puste, aby użyć wbudowanego domyślnego (pokazanego jako placeholder). Zwiększ te wartości, jeśli duże strony są obcinane; zmniejsz je, aby obniżyć koszty API.','Model tier'=>'Poziom modelu','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Jakość (domyślnie — Sonnet / GPT-4o / Gemini Pro)','Light (fast and cost-effective — Haiku / Flash)'=>'Lekki (szybki i ekonomiczny — Haiku / Flash)','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Który poziom modelu użyć do tłumaczenia pełnej strony. Jakość korzysta z modelu skonfigurowanego w tabeli modeli powyżej i jest zalecana do dokładnego, długiego tłumaczenia. Przełącz na Lekki tylko wtedy, gdy priorytetem jest szybkość lub koszt, a treść jest krótka.','Max output tokens'=>'Maksymalna liczba tokenów wyjściowych','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Maksymalna liczba tokenów, które AI może wygenerować w jednej odpowiedzi tłumaczeniowej. Jeśli tłumaczenie jest cicho obcinane na końcu, zwiększ tę wartość. Domyślnie: 16 000.','Max input characters'=>'Maksymalna liczba znaków wejściowych','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Maksymalna liczba znaków treści posta przekazywanej do AI. 0 oznacza brak limitu — pełna treść jest zawsze wysyłana (zalecane). Ustaw wartość różną od zera tylko wtedy, gdy twój dostawca ma ograniczone okno kontekstowe. Ostrzeżenie jest zapisywane w dzienniku błędów PHP za każdym razem, gdy treść jest przycinana.','Quick Translation'=>'Szybkie tłumaczenie','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Szybkie tłumaczenie jest używane w trybie fragmentów — krótkie fragmenty tłumaczone na żądanie z paska narzędzi, edytora lub wyskakujących okienek bloków. Używa osobnej, lżejszej konfiguracji od pełnoekranowego tłumaczenia, aby zachować szybkość i opłacalność odpowiedzi.','Light (default — fast and cost-effective)'=>'Lekki (domyślny — szybki i opłacalny)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Jakość (Sonnet / GPT-4o / Gemini Pro)','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Poziom Light korzysta z szybkiego modelu skonfigurowanego w tabeli modeli powyżej (domyślnie: Haiku / Flash). Przełącz na Jakość, jeśli potrzebujesz takiej samej dokładności tłumaczenia jak w trybie pełnoekranowym dla fragmentów.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Maksymalna liczba tokenów, które AI może wygenerować na szybkie tłumaczenie. Domyślnie: 2000.','Maximum characters accepted from the input field. Default: 8 000.'=>'Maksymalna liczba znaków akceptowanych z pola wejściowego. Domyślnie: 8000.','Content Generator'=>'Generator treści','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Kontroluje budżet tokenów i limity wejścia dla funkcji Generatora treści AI. Pozostaw puste, aby użyć wbudowanych domyślnych ustawień.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Maksymalna liczba tokenów, które AI może wygenerować na jedno uruchomienie. Zwiększ, jeśli pełne artykuły są obcinane. Domyślnie: 8192.','Max hints characters'=>'Maksymalna liczba znaków wskazówek','Maximum characters read from the Hints field. Default: 2 000.'=>'Maksymalna liczba znaków odczytanych z pola wskazówek. Domyślnie: 2000.','Max context characters'=>'Maksymalny kontekst','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Maksymalna liczba znaków istniejącej treści posta przekazywanej do AI jako kontekst startowy, gdy nie podano wskazówek. Domyślnie: 6000.','Maintenance'=>'Utrzymanie','Router'=>'Router','Primary language saved.'=>'Zapisano główny język.','Permalink rules flushed successfully.'=>'Pomyślnie wyczyszczono reguły permalinków.','Language uninstalled. %d post deleted.'=>'Język odinstalowany. %d post usunięty.' . "\0" . 'Język odinstalowany. %d postów usuniętych.' . "\0" . 'Język odinstalowany. %d post usunięty.','%d locale file removed.'=>'Usunięto plik lokalizacji %d.' . "\0" . 'Usunięto pliki lokalizacji: %d.' . "\0" . 'Usunięto pliki lokalizacji: %d.','%d pattern translation removed.'=>'Usunięto %d translację wzorca.' . "\0" . 'Usunięto %d translacje wzorców.' . "\0" . 'Usunięto %d translacji wzorców.','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'Nie można automatycznie usunąć pliku lokalizacji %d (DISALLOW_FILE_MODS jest ustawione). Usuń go ręcznie na serwerze lub za pomocą WP-CLI: wp language core uninstall <locale>.' . "\0" . 'Nie można automatycznie usunąć plików lokalizacji %d (DISALLOW_FILE_MODS jest ustawione). Usuń je ręcznie na serwerze lub za pomocą WP-CLI: wp language core uninstall <locale>.' . "\0" . '','Primary Language'=>'Główny język','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Główny język jest zawsze dostępny na głównym adresie Twojej strony — brak prefiksu URL w trybie ścieżki, brak subdomeny językowej w trybie subdomeny. Wszystkie pozostałe języki używają albo prefiksu /lang/ (np. example.com/de/), albo subdomeny językowej (np. de.example.com), w zależności od ustawienia struktury URL poniżej.','Primary language'=>'Główny język','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Po zmianie głównego języka, odśwież permalink (sekcja poniżej), aby zaktualizować trasowanie URL.','Path prefix — example.com/de/'=>'Przedrostek ścieżki — example.com/pl/ lub example.com/de/ (w zależności od języka)','Subdomain — de.example.com/'=>'Subdomena — pl.example.com/ lub de.example.com/ (w zależności od języka)','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Tryb subdomen wymaga, aby Twój serwer internetowy kierował wszystkie subdomeny językowe (np. de.example.com) do tej instalacji WordPress. Po zmianie trybu odśwież ustawienia permalinków i wyczyść pamięć podręczną. Jeśli Twój adres URL główny zawiera www (np. www.example.com), użyj filtra lf_base_domain, aby ustawić podstawową domenę, tak aby subdomeny były poprawnie konstruowane.','Browser language redirect'=>'Przekierowanie języka przeglądarki','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Przekieruj odwiedzających do ich preferowanego języka na podstawie nagłówka Accept-Language przeglądarki','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Po włączeniu, odwiedzający po raz pierwszy, bez pliku cookie języka i bez prefiksu języka w URL, są przekierowywani do najbliższej pasującej wersji językowej. Przekierowanie jest pomijane, jeśli preferowany język przeglądarki nie znajduje się na liście aktywnych języków routera. Po wybraniu języka przez odwiedzającego za pomocą przełącznika, plik cookie ma pierwszeństwo, a nagłówek przeglądarki jest ignorowany przy kolejnych wizytach.','Query Filter Exclusions'=>'Wyłączenia filtrów zapytań','Lingua Forge scopes secondary WP_Query instances (sidebar widgets, template blocks, plugin lookups) to the active language by injecting a _lf_lang meta constraint. Post types listed here are excluded from that constraint — their queries are always unfiltered.'=>'Lingua Forge ogranicza wtórne instancje WP_Query (widżety boczne, bloki szablonów, wyszukiwania wtyczek) do aktywnego języka poprzez wstrzyknięcie ograniczenia meta _lf_lang. Typy postów wymienione tutaj są wyłączone z tego ograniczenia — ich zapytania są zawsze niefiltrujące.','Contact Form 7 (wpcf7_contact_form), Flamingo contacts and inbound messages (flamingo_contact, flamingo_inbound), and WordPress language-pack sync storage (wp_sync_storage) are excluded automatically. Add any other third-party post types whose content should not be language-filtered, one per line or comma-separated.'=>'Formularz kontaktowy 7 (wpcf7_contact_form), kontakty Flamingo i wiadomości przychodzące (flamingo_contact, flamingo_inbound), oraz synchronizacja pakietu językowego WordPress (wp_sync_storage) są automatycznie wyłączone. Dodaj inne typy postów stron trzecich, których treść nie powinna być filtrowana językowo, jeden na linii lub oddzielony przecinkami.','Excluded post types'=>'Wykluczone typy postów','Post type slugs separated by commas or newlines. Changes take effect immediately on save — no permalink flush required.'=>'Skróty typu post oddzielone przecinkami lub nowymi liniami. Zmiany obowiązują natychmiast po zapisaniu — nie jest wymagana odświeżanie permalinków.','WooCommerce Integration'=>'Integracja WooCommerce','Controls how Lingua Forge integrates with WooCommerce order processing.'=>'Kontroluje, jak Lingua Forge integruje się z przetwarzaniem zamówień WooCommerce.','Order line item source mapping'=>'Mapowanie źródła pozycji zamówienia','Normalize order line item product IDs to the source-language product at checkout'=>'Normalizuj identyfikatory produktów pozycji zamówienia do produktu w języku źródłowym przy kasie','When enabled (recommended), the product ID stored on each WooCommerce order line item is set to the source-language product. This ensures total_sales counts, WC Analytics revenue rows, and third-party ERP exports reference one product ID per SKU rather than one per language version. Trade-off: "View product" links in order emails and My Account lead to the source-language page. Disable only if a connected system relies on translated product IDs in orders. Use the linguaforge_wc_order_item_source_mapping filter for per-item overrides.'=>'Po włączeniu (zalecane) identyfikator produktu zapisany na każdej pozycji zamówienia WooCommerce jest ustawiony na produkt w języku źródłowym. Zapewnia to odniesienia do sumy sprzedaży, wierszy przychodu w analizach WC i eksportów ERP innych firm, odnoszących się do jednego identyfikatora produktu na SKU, a nie na wersję językową. Kompromis: linki "Zobacz produkt" w e-mailach zamówień i Moje konto prowadzą do strony w języku źródłowym. Wyłącz tylko wtedy, gdy system powiązany polega na przetłumaczonych identyfikatorach produktów w zamówieniach. Użyj filtra linguaforge_wc_order_item_source_mapping do nadpisywania na poziomie elementu.','Save Router Settings'=>'Zapisz ustawienia routera','Flush Permalinks'=>'Wyczyść permalinki','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Regeneruje reguły przepisywania WordPress, aby prefiksy URL, specyficzne dla języka slug i przepisywanie archiwów były zsynchronizowane. Konieczne po zmianie głównego języka lub dodaniu nowego wsparcia językowego.','Flush Permalink Rules'=>'Wyczyść reguły permalinków','Active Languages'=>'Aktywne języki','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Języki obecnie znane routerowi (pochodzące z zainstalowanych pakietów lokalizacyjnych WordPress oraz główny język). Zainstaluj dodatkowe pakiety językowe w poniższej sekcji, aby udostępnić więcej języków do routingu i tłumaczeń.','%d locale pack installed.'=>'Zainstalowano %d pakiet lokalizacyjny.' . "\0" . 'Zainstalowano %d pakietów lokalizacyjnych.' . "\0" . 'Zainstalowano %d pakietów lokalizacyjnych.','Install a Language'=>'Zainstaluj język','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Pobierz i zainstaluj pakiet językowy WordPress bezpośrednio z WordPress.org. Po instalacji lokalizacja będzie dostępna do routingu URL i workflow tłumaczeń AI. Lista dostępnych języków jest pobierana na żądanie — kliknij przycisk poniżej, aby ją załadować.','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Instalacja języków jest wyłączona na tym serwerze. Stała DISALLOW_FILE_MODS jest ustawiona w wp-config.php. Zainstaluj pakiety językowe ręcznie za pomocą WP-CLI: wp language core install de_DE','Load available languages'=>'Załaduj dostępne języki','— select a language —'=>'— wybierz język —','Install'=>'Zainstaluj','Language Setup'=>'Ustawienia języka','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Brak skonfigurowanych języków drugorzędnych. Zainstaluj pakiet językowy powyżej, aby włączyć szablony.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Wybierz język, aby zarządzać jego szablonami FSE, częściami szablonów i menu nawigacyjnymi.','Recreate All Languages'=>'Odtwórz wszystkie języki','Recreate All Languages (Templates Only)'=>'Odtwórz wszystkie języki (tylko szablony)','Recreate All Languages (Template Parts Only)'=>'Odtwórz wszystkie języki (tylko części szablonów)','Cancel'=>'Anuluj','Repair Template Metadata'=>'Napraw metadane szablonu','Fixes the Site Editor namespace and _lf_lang tag on all LF-scaffolded FSE templates stored in the database. Run this once after updating from an earlier version of Lingua Forge — it moves WooCommerce-derived templates from the active-theme group to the WooCommerce group in the Site Editor, and ensures all scaffolded templates are discoverable by coverage reports.'=>'Naprawia przestrzeń nazw Edytora witryny i tag _lf_lang we wszystkich szablonach FSE wspieranych przez LF przechowywanych w bazie danych. Uruchom to raz po aktualizacji z wcześniejszej wersji Lingua Forge — przenosi szablony pochodzące z WooCommerce z grupy aktywnego motywu do grupy WooCommerce w Edytorze witryny i zapewnia, że wszystkie szablony wspierane są wykrywalne przez raporty pokrycia.','Repair template metadata'=>'Napraw metadane szablonu','Request failed.'=>'Żądanie nie powiodło się.','Forbidden'=>'Zabronione','Danger Zone'=>'Strefa niebezpieczna','Uninstall %s'=>'Odinstaluj %s','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'Trwale usuwa wszystkie szablony, części szablonów, wzorce, menu nawigacyjne, wpisy, strony, niestandardowe typy wpisów, produkty i warianty produktów powiązane z tym językiem. Usuwa również pliki pakietu lokalizacji WordPress, więc ten język nie pojawia się już w routerze. Ta akcja jest nieodwracalna.','This language matches the WordPress instance locale and cannot be uninstalled.'=>'Ten język odpowiada lokalizacji instancji WordPress i nie można go odinstalować.','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'Czy na pewno chcesz odinstalować %s? Spowoduje to usunięcie całej przetłumaczonej treści dla tego języka i nie można tego cofnąć.','Invalid language code.'=>'Nieprawidłowy kod języka.','This language is protected and cannot be uninstalled.'=>'Ten język jest chroniony i nie można go odinstalować.','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Instalacja języków jest wyłączona na tym serwerze (ustawiono DISALLOW_FILE_MODS).','Invalid locale code.'=>'Nieprawidłowy kod lokalizacji.','Language %s installed successfully.'=>'Język %s został pomyślnie zainstalowany.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Niepowodzenie instalacji pakietu językowego. Język może być już zainstalowany, kod lokalizacji może być niepoprawny lub serwer może blokować zapisy plików.','Navigations'=>'Nawigacje','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Tłumaczenie nawigacji wymaga aktywnego dostawcy AI. Skonfiguruj klucz API w zakładce Klucze API.','Navigation'=>'Nawigacja','Re-translate'=>'Ponowne tłumaczenie','CPT Block Patterns'=>'Wzory bloków CPT','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Wzory bloków zarejestrowane dla niestandardowych typów postów. Użyj przycisku Tłumacz, aby wygenerować wersję językową. Tłumaczona zawartość jest zapisywana tutaj i może być skopiowana do dowolnego posta CPT z edytora bloków lub użyta jako punkt wyjścia dla Wzoru synchronizowanego (Blok wielokrotnego użytku).','Pattern'=>'Wzór','Post Types'=>'Typy postów','✓ Translation saved'=>'✓ Tłumaczenie zapisane','View'=>'Zobacz','Template Parts'=>'Części szablonów','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Kopie części szablonów tematu specyficzne dla języka. Po utworzeniu, szablony są aktualizowane, aby odwoływały się do części specyficznej dla języka.','Re-create all'=>'Odtwórz wszystkie','Translate all'=>'Przetłumacz wszystko','Fix all links'=>'Napraw wszystkie linki','Fix all navs'=>'Napraw wszystkie nawigacje','Part'=>'Część','Status / Actions'=>'Status / Działania','Create'=>'Utwórz','Templates'=>'Szablony','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Szablony FSE utworzone z aktywnego motywu. Utwórz, a następnie dostosuj w Edytorze witryny.','Create missing'=>'Utwórz brakujące','Fix all parts'=>'Napraw wszystkie części','SEO'=>'SEO','Multilingual SEO'=>'Wielojęzyczne SEO','Configure hreflang, Open Graph, Schema.org, sitemaps, and social sharing for every language on your site. Each section below handles one aspect of multilingual SEO.'=>'Konfiguruj hreflang, Open Graph, Schema.org, mapy witryn i udostępnianie społecznościowe dla każdego języka na Twojej stronie. Każda sekcja poniżej obsługuje jeden aspekt wielojęzycznego SEO.','Open Graph &amp; Twitter Cards'=>'Karty Open Graph i Twitter','Schema.org'=>'Schema.org','Sitemap'=>'Mapa witryny','Analysis'=>'Analiza','Compatibility'=>'Zgodność','System'=>'System','Overview'=>'Przegląd','Lingua Forge Settings'=>'Ustawienia Lingua Forge','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge dodaje wielojęzyczne routingi, tłumaczenia oparte na AI, tagi hreflang SEO i przełącznik języków do Twojej witryny WordPress.','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Użyj zakładek na górze tej strony, aby skonfigurować każdą sekcję. Zmiany w zakładce Router są natychmiastowe; zmiany kluczy AI i ustawień modelu obowiązują przy następnym żądaniu AI.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'Po zmianie ustawień struktury URL (prefiks ścieżki ↔ subdomena), zawsze odwiedź Ustawienia → Bezpośrednie odnośniki i kliknij Zapisz zmiany, aby odświeżyć reguły przekierowań.','AI Provider Tab'=>'Zakładka Dostawca AI','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Select the active provider from the dropdown — only one provider is used at a time. Enter an API key for that provider to enable AI features.'=>'Obsługiwani dostawcy: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Wybierz aktywnego dostawcę z listy — używany jest tylko jeden dostawca naraz. Wprowadź klucz API dla tego dostawcy, aby włączyć funkcje AI.','Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Klucze są szyfrowane w stanie spoczynku za pomocą AES-256-GCM z użyciem tajnego klucza specyficznego dla witryny (LINGUAFORGE_SECRET). Nie udostępniaj eksportów bazy danych bez wcześniejszej rotacji klucza.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'Funkcje AI są opcjonalne. Routing językowy, hreflang, przełącznik języków i system grup tłumaczeń działają bez skonfigurowanego dostawcy.','Model tiers'=>'Poziomy modelu','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge używa dwóch poziomów modeli na dostawcę:','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Lekki: używany do meta opisów i generowania fragmentów — szybki, niskokosztowy.','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Jakość: używana do tłumaczeń postów i generowania treści — wyższa jakość, wyższy koszt.','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Pozostaw pole modelu puste, aby użyć wbudowanego domyślnego dla tego poziomu. Tekst zastępczy pokazuje, który model będzie używany.','Translation Limits & Behavior'=>'Limity tłumaczeń i zachowanie','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Limity tłumaczeń: kontroluj, które role użytkowników mogą wywołać tłumaczenie AI, oraz ustaw miesięczny budżet tokenów. Przekroczenie budżetu wstrzymuje wywołania AI do resetu miesiąca.','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Zachowanie: wybierz preset AI (Literal, Balanced, Creative), dodaj instrukcje niestandardowe dla całej witryny, włącz lub wyłącz automatyczne tłumaczenie po zapisaniu posta oraz skonfiguruj Pamięć tłumaczeń.','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'Pamięć tłumaczeń buforuje wyniki AI na podstawie hasha treści, pary językowej, dostawcy i modelu. Edycja posta unieważnia wpis w pamięci podręcznej, więc następne tłumaczenie pobiera świeży wynik.','Router Tab'=>'Zakładka routera','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Język główny: język, w którym napisane są Twoje istniejące treści. Wszystkie tłumaczenia są tworzone z tego języka; zmiana go nie przenosi ani nie usuwa żadnych postów.','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'Struktura URL: tryb prefiksu ścieżki (example.com/de/) nie wymaga zmian na serwerze. Tryb subdomeny (de.example.com) wymaga rekordu DNS typu wildcard, certyfikatu SSL wildcard oraz zmiany konfiguracji serwera — zobacz przewodnik konfiguracji serwera.','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Aktywne języki: dodaj każdy język, który chcesz obsługiwać. Każdy język otrzymuje prefiks URL lub subdomenę oraz tag hreflang w sekcji &lt;head&gt; strony.','WP site language requirement'=>'Wymaganie dotyczące języka witryny WP','The WordPress site language (Settings → General → Site Language) must be set to one of the languages you use for content — either the primary content language or one of the secondary languages. It cannot be a language that has no content on the site.'=>'Język witryny WordPress (Ustawienia → Ogólne → Język witryny) musi być ustawiony na jeden z języków, których używasz do treści — albo główny język treści, albo jeden z języków drugorzędnych. Nie może to być język, który nie ma treści na stronie.','Example of a supported configuration: WP site language = CA (Catalan), content languages = CA + ES.'=>'Przykład obsługiwanej konfiguracji: język witryny WP = CA (Kataloński), języki treści = CA + ES.','Example of an unsupported configuration: WP site language = EN (English), content languages = CA + ES only. English is not a content language, so Lingua Forge cannot map the WP locale to any translation group.'=>'Przykład nieobsługiwanej konfiguracji: język witryny WP = EN (Angielski), języki treści = CA + ES tylko. Angielski nie jest językiem treści, więc Lingua Forge nie może przypisać lokalizacji WP do żadnej grupy tłumaczeń.','When the WP site language is not a content language: WooCommerce product queries return zero results on all catalogue blocks; product image delegation fails; all language-filtered content queries break; the language switcher may show a spurious non-content language option. If you see a red configuration alert at the top of the Router or System tab, correct the site language first.'=>'Gdy język witryny WP nie jest językiem treści: zapytania o produkty WooCommerce zwracają zero wyników we wszystkich blokach katalogu; delegacja obrazów produktów zawodzi; wszystkie zapytania o treści filtrowane według języka się psują; przełącznik języków może wyświetlać nieprawidłową opcję języka nie będącego treścią. Jeśli na górze zakładki Router lub System pojawi się czerwony alert konfiguracji, najpierw popraw język witryny.','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'Lokalizacja FSE: tworzenie szkieletu, tłumaczenie i naprawa linków w szablonach i częściach szablonów Full Site Editing bezpośrednio z tego zakładki.','Glossary Tab'=>'Zakładka słownika','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Przypnij terminy, które nie mogą być tłumaczone lub muszą zawsze być renderowane w określony sposób (np. nazwy marek, nazwy produktów, akronimy). Ograniczenia glosariusza są wstrzykiwane do każdego żądania tłumaczenia AI dla wszystkich funkcji: tłumaczenia postów, meta opisów, fragmentów i tłumaczeń szablonów FSE.','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Dodaj jeden termin na wiersz. Zarówno termin źródłowy, jak i docelowy są wymagane. Para języków określa, do których zadań tłumaczeniowych obowiązuje ograniczenie.','SEO Tab'=>'Zakładka SEO','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'Lingua Forge to kompletne rozwiązanie SEO wielojęzycznego. Nie jest wymagana żadna dodatkowa wtyczka SEO ani mapa witryny.','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'Co zapewnia LF: tagi hreflang dla każdego skonfigurowanego języka, tagi Open Graph i Twitter Card z og:locale i og:locale:alternate, Schema.org JSON-LD z adnotacjami inLanguage oraz dedykowana wielojęzyczna mapa witryny pod /lf-sitemap.xml z wpisami alternatywnych odnośników xhtml:link dla wszystkich grup tłumaczeń.','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'Mapa witryny jest automatycznie ogłaszana w robots.txt. Wszystkie główne wyszukiwarki — Google, Bing, Yandex — odkrywają ją z robots.txt. Nie jest wymagana ręczna submisja.','SEO plugins and conflict avoidance:'=>'Wtyczki SEO i unikanie konfliktów:','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'Jeśli masz zainstalowane Yoast SEO, Rank Math, All in One SEO lub SEOPress, Lingua Forge wykrywa je i dostosowuje, aby uniknąć duplikacji outputu. Dla hreflang LF całkowicie przejmuje kontrolę i tłumi output wtyczki, ponieważ te wtyczki nie mogą poprawnie generować hreflang dla wielojęzycznej konfiguracji routingu. Dla Open Graph LF dodaje tylko og:locale i og:locale:alternate — sygnały wielojęzyczności, których wtyczka nie może zapewnić — i pozostawia podstawowy zestaw OG w wtyczce. Dla Schema.org LF całkowicie wyłącza własny output, aby uniknąć konfliktów w grafach JSON-LD.','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'Zakładka SEO → Kompatybilność pokazuje status wykrywania na żywo i wyjaśnia dokładnie, co LF robi dla każdej funkcji.','SEO Scores'=>'Wyniki SEO','SEO Score System'=>'System oceniania SEO','Score computation'=>'Obliczanie wyniku','Each post is scored 0–100 from six rule-based metrics: title, meta description, word count, heading structure, image alt coverage, and internal links. Ten points are always awarded for reading time (informational only). The remaining 90 points are distributed across the other metrics with weights that vary by content profile (see below).'=>'Każdy post jest oceniany w skali 0–100 na podstawie sześciu metryk opartych na zasadach: tytuł, meta opis, liczba słów, struktura nagłówków, pokrycie obrazów alt i wewnętrzne linki. Za czas czytania zawsze przyznaje się 10 punktów (tylko informacyjnie). Pozostałe 90 punktów jest rozdzielane pomiędzy pozostałe metryki z wagami zmieniającymi się w zależności od profilu treści (patrz poniżej).','Each metric yields one of four statuses: ok (full weight), warn (50 % of weight), fail (0), or info (0, no penalty). A score ≥ 80 is green, 50–79 amber, below 50 red.'=>'Każda metryka daje jeden z czterech statusów: ok (pełna waga), ostrzeżenie (50% wagi), niepowodzenie (0), lub informacja (0, brak kary). Wynik ≥ 80 jest zielony, 50–79 bursztynowy, poniżej 50 czerwony.','Title scoring rules (all profiles): fail if empty; warn if fewer than 10 characters; warn if only one word; warn if longer than the profile\'s SERP limit (60 chars for Blog, 70 for Product/Landing); ok if at least 10 characters, at least 2 words, and within the SERP limit.'=>'Zasady oceniania tytułów (wszystkie profile): niepowodzenie jeśli puste; ostrzeżenie jeśli mniej niż 10 znaków; ostrzeżenie jeśli tylko jedno słowo; ostrzeżenie jeśli dłuższy niż limit SERP profilu (60 znaków dla Bloga, 70 dla Produktu/Landing); OK jeśli co najmniej 10 znaków, co najmniej 2 słowa i w limicie SERP.','Content profiles and weights'=>'Profile treści i wagi','Profiles adapt thresholds and weights to the type of content being analysed. Profile is resolved automatically; you can override it per analysis run from the profile dropdown.'=>'Profile dostosowują progi i wagi do rodzaju analizowanej treści. Profil jest rozwiązywany automatycznie; możesz go nadpisać dla każdej analizy z menu rozwijanego profilu.','Blog / Editorial (default)'=>'Blog / Redakcja (domyślnie)','Title 15 pts · Meta description 20 pts · Word count 15 pts · Headings 20 pts · Images 10 pts · Links 10 pts. Title SERP limit 60 chars; meta 120–210 chars; word count warns below 300, fails below 100; H2 required; internal links required.'=>'Tytuł 15 pkt · Opis meta 20 pkt · Liczba słów 15 pkt · Nagłówki 20 pkt · Obrazy 10 pkt · Linki 10 pkt. Limit tytułu w SERP 60 znaków; meta 120–210 znaków; ostrzeżenie o liczbie słów poniżej 300, błąd poniżej 100; wymagana H2; wymagane linki wewnętrzne.','Auto-detected for WooCommerce products. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 5 pts · Images 20 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 80, fails below 40; H2 and internal links optional.'=>'Automatycznie wykryte dla produktów WooCommerce. Tytuł 20 pkt · Meta opis 30 pkt · Liczba słów 15 pkt · Nagłówki 5 pkt · Obrazy 20 pkt · Linki 0 pkt. Limit tytułu w SERP 70 znaków; ostrzeżenie przy poniżej 80 słów, niepowodzenie poniżej 40; H2 i wewnętrzne linki opcjonalne.','Auto-detected for the static front page; can be selected manually. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 10 pts · Images 15 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 150, fails below 60; H2 and internal links optional.'=>'Automatycznie wykryte dla statycznej strony głównej; można wybrać ręcznie. Tytuł 20 pkt · Meta opis 30 pkt · Liczba słów 15 pkt · Nagłówki 10 pkt · Obrazy 15 pkt · Linki 0 pkt. Limit tytułu w SERP 70 znaków; ostrzeżenie przy poniżej 150 słów, niepowodzenie poniżej 60; H2 i wewnętrzne linki opcjonalne.','Heading structure rules'=>'Zasady struktury nagłówków','Exactly one H1 is required. The H1 is normally the post title rendered by the theme — it is read from the live rendered page when possible, and from post content as a fallback.'=>'Dokładnie jeden H1 jest wymagany. H1 to zazwyczaj tytuł posta renderowany przez motyw — odczytywany z aktualnie wyświetlanej strony, gdy to możliwe, a w razie braku z treści posta.','When the Blog profile requires an H2 and none is found, the analyser first checks for H3 subheadings before issuing a warning. Accordion and Details blocks default to H3 for their headers; those H3s are accepted as valid structure and produce an ok result, not a warning.'=>'Gdy profil Blog wymaga H2, a nie ma go, analizator najpierw sprawdza podtytuły H3, zanim wyda ostrzeżenie. Bloki Accordion i Details domyślnie mają H3 jako nagłówki; te H3 są akceptowane jako poprawna struktura i dają wynik OK, nie ostrzeżenie.','Short content (3 paragraphs or fewer) is never penalised for missing subheadings, regardless of profile. A concise page does not benefit from forced heading structure.'=>'Krótka treść (do 3 akapitów) nigdy nie jest karana za brak podtytułów, niezależnie od profilu. Zwięzła strona nie korzysta na wymuszonej strukturze nagłówków.','"Treat H2 as H1 equivalent" (Settings → SEO → Analysis): enable this when your theme renders the post title inside an H2 instead of an H1. The analyser promotes the first H2 to H1 so the score is not incorrectly penalised.'=>'"Traktuj H2 jako równoważne H1" (Ustawienia → SEO → Analiza): włącz to, gdy Twój motyw renderuje tytuł posta wewnątrz H2 zamiast H1. Analizator promuje pierwszy H2 do H1, aby wynik nie był nieprawidłowo penalizowany.','Score history and badges'=>'Historia wyników i odznaki','Every time a post is analysed the score is stored in post meta. The post list Lang column shows a colour-coded "SEO N" badge for any post that has been analysed at least once. When two scores are stored a delta indicator (↑N / ↓N) shows the change since the previous run.'=>'Za każdym razem, gdy post jest analizowany, wynik jest przechowywany w meta danych posta. Kolumna języka na liście postów pokazuje kolorową odznakę "SEO N" dla każdego posta, który był analizowany przynajmniej raz. Gdy zapisane są dwa wyniki, wskaźnik delta (↑N / ↓N) pokazuje zmianę od poprzedniego uruchomienia.','AI Usage & Cache Tab'=>'Zakładka Użycie AI i Pamięć podręczna','Token usage'=>'Użycie tokenów','The usage table shows AI token consumption broken down by feature (translation, meta description, excerpt, FSE template, batch analysis), provider, and model. Use the date-range buttons to filter by today, last 7 days, last 30 days, or all time.'=>'Tabela użycia pokazuje zużycie tokenów AI podzielone według funkcji (tłumaczenie, metaopis, fragment, szablon FSE, analiza wsadowa), dostawcy i modelu. Użyj przycisków zakresu dat, aby filtrować według dzisiaj, ostatnich 7 dni, ostatnich 30 dni lub wszystko.','The daily quota (configured in Behavior → Limits) is tracked here. When the quota is reached, AI calls are suspended for the rest of the day. The table shows how much of the quota has been consumed.'=>'Dzienny limit (konfigurowany w Zachowaniu → Limity) jest śledzony tutaj. Gdy limit zostanie osiągnięty, wywołania AI są zawieszane na resztę dnia. Tabela pokazuje, ile limitu zostało zużyte.','Translation caching'=>'Buforowanie tłumaczeń','Lingua Forge uses two independent caching layers to reduce redundant AI API calls:'=>'Lingua Forge używa dwóch niezależnych warstw pamięci podręcznej, aby zmniejszyć liczbę zbędnych wywołań API AI:','Stores raw AI responses keyed by content hash, language pair, provider, model, and preset. Cache entries are invalidated automatically when the source post content changes. Clear individual post entries or the whole cache from this tab.'=>'Przechowuje surowe odpowiedzi AI kluczem opartym na haszowaniu treści, parze języków, dostawcy, modelu i preset. Wpisy pamięci podręcznej są automatycznie unieważniane, gdy zmienia się treść źródłowego posta. Wyczyść pojedyncze wpisy lub całą pamięć podręczną z tego zakładki.','Stores the full translated post output per content hash. Opt-in (enabled in Behavior). Speeds up repeated translations of unchanged content. Clear it here when you want to force a fresh AI pass regardless of whether the content has changed.'=>'Przechowuje pełny przetłumaczony wynik posta na podstawie hasza treści. Zgoda na to (włączona w Zachowaniu). Przyspiesza powtarzające się tłumaczenia niezmienionej treści. Wyczyść to tutaj, gdy chcesz wymusić nową rundę AI, niezależnie od tego, czy treść się zmieniła.','Maintenance Tab'=>'Zakładka konserwacji','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Nadpisywanie języków: zarządzaj niestandardowymi plikami .po/.mo dla tekstów interfejsu Lingua Forge. Używaj tego zamiast bezpośredniej edycji plików wtyczki — nadpisy zachowują się po aktualizacjach.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Debugowanie: włącz dziennik debugowania, aby rejestrować zapytania AI i odpowiedzi API do lokalnego pliku. Wyłącz po rozwiązaniu problemów — tryb debugowania zapisuje plik przy każdym żądaniu AI.','Uninstall Behaviour: controls what is deleted when the plugin is removed from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments, translation relationships, meta descriptions, glossary, and Translation Memory are kept by default so an accidental uninstall or reinstall can pick up where it left off. Enable "Delete content data on uninstall" only when you are fully removing multilingual support from the site — this cannot be undone.'=>'Zachowanie odinstalowania: kontroluje, co jest usuwane po odinstalowaniu wtyczki z Wtyczki → Zainstalowane wtyczki → Usuń. Ustawienia wtyczki i pamięć podręczna AI są zawsze usuwane. Przydziały językowe, relacje tłumaczeń, opisy meta, słowniki i Pamięć tłumaczeń są domyślnie zachowywane, aby przypadkowe odinstalowanie lub ponowne zainstalowanie mogło kontynuować tam, gdzie przerwano. Włącz "Usuń dane zawartości przy odinstalowaniu" tylko wtedy, gdy całkowicie usuwasz obsługę wielojęzyczną ze strony — nie można tego cofnąć.','System Tab'=>'Zakładka System','Read-only diagnostics for the current installation. No settings are changed here — use it to verify configuration, spot problems, and gather information for bug reports.'=>'Diagnostyka tylko do odczytu dla bieżącej instalacji. Żadne ustawienia nie są tutaj zmieniane — użyj tego, aby zweryfikować konfigurację, wykryć problemy i zebrać informacje do zgłoszeń błędów.','Sections'=>'Sekcje','Lingua Forge, WordPress, and PHP versions; active theme; URL structure; WP site language and primary content language. A red indicator next to the WP site language means it is not one of the active content languages — fix it in Settings → General before anything else.'=>'Wersje Lingua Forge, WordPress i PHP; aktywny motyw; struktura URL; język witryny WP i główny język treści. Czerwony wskaźnik obok języka witryny WP oznacza, że nie jest on jednym z aktywnych języków treści — napraw to w Ustawieniach → Ogólne.','Active provider, configured keys, model tier selections, preset, and daily quota.'=>'Aktywny dostawca, skonfigurowane klucze, wybory poziomu modelu, preset i dzienny limit.','Confirms the permalink structure is compatible with Lingua Forge path routing. Plain and numeric-only structures are not supported.'=>'Potwierdza, że struktura permalinków jest zgodna z routingiem ścieżek Lingua Forge. Struktury proste i tylko numeryczne nie są obsługiwane.','Lists any active third-party SEO plugins. Lingua Forge adapts its output when these are present — see Settings → SEO → Compatibility for the per-feature breakdown.'=>'Wymienia aktywne wtyczki SEO innych firm. Lingua Forge dostosowuje swoje wyjście, gdy są one obecne — zobacz Ustawienia → SEO → Kompatybilność dla szczegółowego podziału na funkcje.','WooCommerce version, order storage mode (CPT / HPOS / shared), and a per-language translation coverage table for the four built-in WC pages (Shop, Cart, Checkout, My Account).'=>'Wersja WooCommerce, tryb przechowywania zamówień (CPT / HPOS / shared) oraz tabela pokrycia tłumaczeń na język dla czterech wbudowanych stron WC (Sklep, Koszyk, Realizacja zamówienia, Moje konto).','Lists post types that have published posts without a _lf_lang meta value. Posts missing this tag are invisible to all language filters. Use the Repair button to tag them with the source language, or Exclude to remove the post type from language routing entirely.'=>'Wymienia typy postów, które mają opublikowane posty bez wartości meta _lf_lang. Posty bez tego tagu są niewidoczne dla wszystkich filtrów językowych. Użyj przycisku Napraw, aby oznaczyć je jako w języku źródłowym, lub Wyklucz, aby całkowicie usunąć typ postu z routingu językowego.','Collapsible dump of all LF-owned entries in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts after adding a new language.'=>'Rozkładanie wszystkich wpisów LF w $wp_rewrite->extra_rules_top. Przydatne do diagnozowania błędów 404 lub konfliktów routingu po dodaniu nowego języka.','One-click copy of a plain-text system summary covering all of the above sections. Paste this into a GitHub issue or support request so the full environment is visible at a glance.'=>'Jednoklikowe kopiowanie podsumowania systemu w formacie tekstowym obejmującego wszystkie powyższe sekcje. Wklej to do zgłoszenia na GitHub lub zgłoszenia wsparcia, aby pełne środowisko było widoczne na pierwszy rzut oka.','Found a bug or unexpected behaviour? Please open an issue on GitHub — include the Debug Info block above and a short description of what you expected vs. what happened.'=>'Znalazłeś błąd lub nieoczekiwane zachowanie? Zgłoś problem na GitHub — dołącz blok Debug Info powyżej i krótki opis tego, czego się spodziewałeś vs. co się stało.','Open an issue →'=>'Otwórz zgłoszenie →','Getting started'=>'Rozpoczęcie','Server setup (subdomain)'=>'Konfiguracja serwera (subdomena)','Translation workflow'=>'Przepływ pracy tłumaczeń','Language switcher'=>'Przełącznik języków','WP-CLI reference'=>'Odwołanie do WP-CLI','Integration API'=>'API integracji','Documentation'=>'Dokumentacja','Report an issue on GitHub'=>'Zgłoś problem na GitHubie','Anthropic (Claude)'=>'Anthropic (Claude)','OpenAI (GPT)'=>'OpenAI (GPT)','Google (Gemini)'=>'Google (Gemini)','WordPress AI Client (WP 7.0+)'=>'Klient AI WordPress (WP 7.0+)','Meta Description, Excerpt Generator'=>'Meta Description, Generator fragmentów','Translation, Content Generator'=>'Tłumaczenie, Generator treści','Testing…'=>'Testowanie…','✓ Connection OK'=>'✓ Połączenie OK','✗ Failed:'=>'✗ Niepowodzenie:','No response from provider — check the error log for details.'=>'Brak odpowiedzi od dostawcy — sprawdź dziennik błędów po szczegóły.','Network error — could not reach the WordPress AJAX endpoint.'=>'Błąd sieci — nie można nawiązać kontaktu z punktem końcowym AJAX WordPress.','Translating a real post with this model…'=>'Tłumaczenie rzeczywistego postu tym modelem…','preset'=>'preset','Loading…'=>'Wczytywanie…','Installing…'=>'Instalacja…','✓ Language installed.'=>'✓ Język zainstalowany.','✗ Error:'=>'✗ Błąd:','Creating…'=>'Tworzenie…','✓ All templates created.'=>'✓ Wszystkie szablony utworzone.','Some templates could not be created.'=>'Niektórych szablonów nie można utworzyć.','Recreating…'=>'Odtwarzanie…','✓ All templates recreated.'=>'✓ Wszystkie szablony odtworzone.','Some templates could not be recreated.'=>'Nie można było odtworzyć niektórych szablonów.','This overwrites this template with a fresh copy from the active theme, discarding any Site Editor customisations made to it. This cannot be undone. Continue?'=>'To zastępuje ten szablon świeżą kopią z aktywnego motywu, odrzucając wszelkie dostosowania edytora witryny do niego. Nie można tego cofnąć. Kontynuować?','This overwrites every template with a fresh copy from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'To zastępuje każdy szablon świeżą kopią z aktywnego motywu, odrzucając wszelkie dostosowania edytora witryny do nich. Nie można tego cofnąć. Kontynuować?','✓ All parts recreated.'=>'✓ Wszystkie części odtworzone.','Some parts could not be recreated.'=>'Nie można było odtworzyć niektórych części.','This overwrites this template part with a fresh copy from the active theme, discarding any Site Editor customisations made to it. This cannot be undone. Continue?'=>'To zastępuje tę część szablonu świeżą kopią z aktywnego motywu, odrzucając wszelkie dostosowania edytora witryny do niej. Nie można tego cofnąć. Kontynuować?','This overwrites every template part with a fresh copy from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'To zastępuje każdą część szablonu świeżą kopią z aktywnego motywu, odrzucając wszelkie dostosowania edytora witryny do nich. Nie można tego cofnąć. Kontynuować?','✓ All parts created.'=>'✓ Wszystkie części utworzone.','Some parts could not be created.'=>'Niektórych części nie można utworzyć.','✓ All translated.'=>'✓ Wszystko przetłumaczone.','Some translations failed.'=>'Niektóre tłumaczenia nie powiodły się.','Review carefully — links and slugs not updated.'=>'Dokładnie sprawdź — linki i slug nie zostały zaktualizowane.','Fixing…'=>'Naprawianie…','✓ Links fixed.'=>'✓ Linki naprawione.','Some link fixes failed.'=>'Niektóre naprawy linków nie powiodły się.','✓ Parts fixed.'=>'✓ Części naprawione.','Some part fixes failed.'=>'Niektóre naprawy części nie powiodły się.','✓ Nav refs fixed.'=>'✓ Naprawione odwołania nawigacyjne.','Some nav ref fixes failed.'=>'Niektóre naprawy odwołań nawigacyjnych nie powiodły się.','✓ Pattern translated.'=>'✓ Wzorzec przetłumaczony.','Pattern translation failed.'=>'Tłumaczenie wzorca nie powiodło się.','Hide'=>'Ukryj','Re-create all templates'=>'Odtwórz wszystkie szablony','Re-create all parts'=>'Odtwórz wszystkie części','This runs Re-create all templates, Re-create all parts, Translate all, Fix all parts, and Fix all links for every one of your {total} active languages, one language at a time. It overwrites existing templates and parts with fresh copies from the active theme (discarding Site Editor customisations) and re-translates content — none of this can be undone. Translate all makes real AI API calls for every template and part, which may take a while and may incur cost depending on your provider. Continue?'=>'To uruchamia Odtwórz wszystkie szablony, Odtwórz wszystkie części, Przetłumacz wszystkie, Napraw wszystkie części i Napraw wszystkie linki dla każdego z {total} aktywnych języków, po jednym języku na raz. Zastępuje istniejące szablony i części świeżymi kopiami z aktywnego motywu (odrzucając dostosowania edytora witryny) i ponownie tłumaczy zawartość — nic z tego nie można cofnąć. Przetłumacz wszystkie wykonuje rzeczywiste połączenia AI API dla każdego szablonu i części, co może trwać długo i może pociągnąć za sobą koszty w zależności od dostawcy. Kontynuować?','This runs Re-create all templates, Translate all, Fix all parts, and Fix all links for every one of your {total} active languages, one language at a time — template parts (headers, footers, etc.) are left untouched. It overwrites existing templates with fresh copies from the active theme (discarding Site Editor customisations) and re-translates content — none of this can be undone. Translate all makes real AI API calls for every template, which may take a while and may incur cost depending on your provider. Continue?'=>'Uruchamia funkcje: Ponownie utwórz wszystkie szablony, Przetłumacz wszystko, Napraw wszystkie części i Napraw wszystkie linki dla każdego z Twoich {total} aktywnych języków, jeden język naraz — części szablonów (nagłówki, stopki itp.) pozostają niezmienione. Zastępuje istniejące szablony świeżymi kopiami z aktywnego motywu (odrzucając dostosowania edytora witryny) i ponownie tłumaczy zawartość — żadne z tego nie można cofnąć. Funkcja Przetłumacz wszystko wykonuje rzeczywiste wywołania API sztucznej inteligencji dla każdego szablonu, co może chwilę potrwać i może wiązać się z kosztami w zależności od Twojego dostawcy. Kontynuować?','This runs Re-create all parts (headers, footers, and every other template part) for every one of your {total} active languages, one language at a time. It overwrites existing template parts with fresh copies from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Uruchamia funkcję Ponownie utwórz wszystkie części (nagłówki, stopki i każdą inną część szablonu) dla każdego z Twoich {total} aktywnych języków, jeden język naraz. Zastępuje istniejące części szablonów świeżymi kopiami z aktywnego motywu, odrzucając wszelkie dostosowania dokonane w edytorze witryny. Tego nie można cofnąć. Kontynuować?','Starting…'=>'Rozpoczynanie…','Processing {lang} ({index} of {total}) — {step}…'=>'Przetwarzanie {lang} ({index} z {total}) — {step}…','Cancelled.'=>'Anulowano.','{done} of {total} languages processed.'=>'{done} z {total} języków przetworzonych.','⚠ Done with issues.'=>'⚠ Ukończono z problemami.','✓ All {total} languages processed.'=>'✓ Wszystkie {total} języki przetworzone.','Built-in preset instructions:'=>'Wbudowane instrukcje presetów:','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Brak wbudowanych instrukcji — każda funkcja AI korzysta z własnych dostrojonych domyślnych ustawień. Wypełnij poniższe pole Instrukcje niestandardowe, aby dodać własne zasady dla całej witryny.','Modified'=>'Zmodyfikowano','edit'=>'edytuj','No published posts found for the selected filters.'=>'Nie znaleziono opublikowanych postów dla wybranych filtrów.','Just now'=>'Właśnie teraz','Score'=>'Wynik','Source title'=>'Tytuł źródłowy','Multilingual SEO overview'=>'Przegląd wielojęzycznego SEO','Scores are a signal, not a verdict. Some content is structurally limited — very short pages, landing pages with little body text, or pages whose purpose is navigation rather than information may score lower by nature. Use this overview to spot genuine parity gaps across languages, not to chase a number.'=>'Wyniki są sygnałem, a nie werdyktem. Niektóre treści są ograniczone strukturalnie — bardzo krótkie strony, strony docelowe z niewielką treścią, lub strony, których celem jest nawigacja, a nie informacja, mogą mieć niższy wynik z natury. Użyj tego przeglądu, aby zauważyć prawdziwe luki w parytetach między językami, a nie ścigać się za liczbą.','This is a WooCommerce system page (Shop, Cart, Checkout, etc.). Its content is managed by WooCommerce — the score reflects structural signals only, not user-editable SEO content.'=>'To jest strona systemowa WooCommerce (Sklep, Koszyk, Realizacja zamówienia itp.). Jej treść jest zarządzana przez WooCommerce — wynik odzwierciedla wyłącznie sygnały strukturalne, a nie edytowalną treść SEO.','Settings'=>'Ustawienia','You do not have permission to manage these settings.'=>'Nie masz uprawnień do zarządzania tymi ustawieniami.','Lingua Forge — Settings'=>'Lingua Forge — Ustawienia','Settings saved.'=>'Ustawienia zapisane.','Save Settings'=>'Zapisz ustawienia','Standard'=>'Standardowy','Technical / Scientific'=>'Techniczny / Naukowy','Legal / Compliance'=>'Prawny / Zgodność','Creative / Marketing'=>'Kreatywny / Marketing','Lingua Forge — AI Usage Statistics'=>'Lingua Forge — Statystyka użycia AI','Lingua Forge AI Usage Statistics'=>'Statystyki Użytkowania Lingua Forge AI','Date'=>'Data','Request count'=>'Liczba żądań','Full Article'=>'Pełny artykuł','Introduction only'=>'Tylko wprowadzenie','Structured Outline'=>'Strukturalny plan','Generate Content'=>'Generuj treść','Hints'=>'Wskazówki','Key points, ideas, or structure to build from…'=>'Kluczowe punkty, pomysły lub struktura do zbudowania...','Tone'=>'Ton','Output'=>'Wynik','Generate Excerpt'=>'Wygeneruj fragment','Generate Meta Description'=>'Wygeneruj metaopis','Translate Content'=>'Tłumacz treść','Mode'=>'Tryb','Full post'=>'Pełny post','Translate chunk'=>'Tłumacz fragment','Target Language'=>'Język docelowy','Text to translate'=>'Tekst do tłumaczenia','Paste a footnote, sentence, or any snippet here…'=>'Wklej tutaj przypis, zdanie lub dowolny fragment…','Also generate meta description'=>'Również wygeneruj metaopis','Translated Labels'=>'Przetłumaczone etykiety','Attribute label displayed in this language. Leave empty to use the default label.'=>'Etykieta atrybutu wyświetlana w tym języku. Pozostaw puste, aby użyć domyślnej etykiety.','Translate all labels (AI)'=>'Przetłumacz wszystkie etykiety (AI)','Insufficient permissions.'=>'Niewystarczające uprawnienia.','All labels already translated.'=>'Wszystkie etykiety są już przetłumaczone.','%d label(s) translated.'=>'%d etykieta(y) przetłumaczona(e).','Translation failed. Check the browser console.'=>'Tłumaczenie nie powiodło się. Sprawdź konsolę przeglądarki.','Cannot write to product %1$d: it is a translated version (language: %2$s)%3$s. Operational data (price, stock, SKU, dimensions) must be updated on the source product. Resolve the source product ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations'=>'Nie można zapisać produktu %1$d: jest to wersja tłumaczona (język: %2$s)%3$s. Dane operacyjne (cena, stan magazynowy, SKU, wymiary) muszą być aktualizowane na produkcie źródłowym. Rozwiąż ID produktu źródłowego za pomocą: GET /wp-json/lingua-forge/v1/post/%4$d/translations','Translated Names'=>'Tłumaczone nazwy','Name displayed in this language. Leave empty to use the source name.'=>'Nazwa wyświetlana w tym języku. Pozostaw puste, aby użyć nazwy źródłowej.','Translate all tags (AI)'=>'Przetłumacz wszystkie tagi (AI)','Translate all categories (AI)'=>'Przetłumacz wszystkie kategorie (AI)','Translate all %s terms (AI)'=>'Przetłumacz wszystkie terminy %s (AI)','Translate all terms (AI)'=>'Przetłumacz wszystkie terminy (AI)','Invalid taxonomy.'=>'Nieprawidłowa taksonomia.','No terms found.'=>'Nie znaleziono terminów.','%d term(s) translated.'=>'%d termin(ów) przetłumaczonych.','%d already translated — <a href="#" class="lf-force-translate">force retranslate</a>'=>'%d już przetłumaczone — <a href="#" class="lf-force-translate">wymuś ponowne tłumaczenie</a>','%1$d translated, %2$d skipped.'=>'%1$d przetłumaczono, %2$d pominięto.','Order placed in language: %s'=>'Zamówienie złożone w języku: %s','Invalid API key — double-check the key entered in the AI Provider settings.'=>'Nieprawidłowy klucz API — sprawdź dwukrotnie klucz w ustawieniach dostawcy AI.','Payment required — your account has no remaining credits.'=>'Wymagana płatność — Twoje konto nie ma już dostępnych kredytów.','Access forbidden — your account may be suspended or the key lacks the required permissions.'=>'Dostęp zabroniony — Twoje konto może być zawieszone lub klucz nie ma wymaganych uprawnień.','Rate limited — too many requests sent to the provider; wait a moment and try again.'=>'Ograniczenie szybkości — zbyt wiele żądań wysłanych do dostawcy; odczekaj chwilę i spróbuj ponownie.','Provider service temporarily unavailable — try again in a moment.'=>'Usługa dostawcy tymczasowo niedostępna — spróbuj ponownie za chwilę.','Provider error (HTTP %1$d): %2$s'=>'Błąd dostawcy (HTTP %1$d): %2$s','Unexpected provider error (HTTP %d).'=>'Nieoczekiwany błąd dostawcy (HTTP %d).','No API key configured — enter your key in the AI Provider settings.'=>'Nie skonfigurowano klucza API — wprowadź swój klucz w ustawieniach dostawcy AI.','Network error — could not reach the provider: %s'=>'Błąd sieci — nie można nawiązać kontaktu z dostawcą: %s','No credits remaining — top up your OpenAI account at platform.openai.com/account/billing.'=>'Brak kredytów — doładuj swoje konto OpenAI na platformie openai.com/account/billing.','WordPress AI Client requires WordPress 7.0 or later.'=>'Klient AI WordPress wymaga WordPress 7.0 lub nowszego.','No user message found in the message array.'=>'Nie znaleziono wiadomości użytkownika w tablicy wiadomości.','No text-generation model is available. Configure an AI provider in Settings → Connectors.'=>'Nie ma dostępnego modelu generowania tekstu. Skonfiguruj dostawcę AI w Ustawieniach → Łączniki.','Too many AI requests. Please retry in %d seconds.'=>'Zbyt wiele żądań AI. Spróbuj ponownie za %d sekund.','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Dzienne limity AI osiągnięte (%1$d żądań). Reset o %2$s UTC.','View Lingua Forge details'=>'Zobacz szczegóły Lingua Forge','View details'=>'Zobacz szczegóły','Visit plugin site'=>'Odwiedź stronę wtyczki','Lingua Forge update blocked: download host "%s" is not on the allowlist.'=>'Aktualizacja Lingua Forge zablokowana: host pobierania "%s" nie jest na liście dozwolonych.','Lingua Forge update blocked: SHA-256 of the downloaded package does not match the manifest. The file may have been tampered with.'=>'Aktualizacja Lingua Forge zablokowana: SHA-256 pobranego pakietu nie pasuje do manifestu. Plik mógł zostać zmodyfikowany.','Exclude from navigation menus'=>'Wyklucz z menu nawigacyjnych','Apply to all language versions'=>'Zastosuj do wszystkich wersji językowych','Noindex (hide this language version from search engines)'=>'Noindex (ukryj tę wersję językową przed wyszukiwarkami)','%d language not yet linked'=>'%d język jeszcze nie powiązany' . "\0" . '%d języków jeszcze nie powiązanych' . "\0" . '%d języków jeszcze nie powiązanych','This is the source page. Footnotes are edited directly in the block editor.'=>'To jest strona źródłowa. Przypisy są edytowane bezpośrednio w edytorze bloków.','No source page linked yet.'=>'Jeszcze nie powiązano strony źródłowej.','The source page has no footnotes.'=>'Strona źródłowa nie ma przypisów.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Te przypisy pochodzą ze strony źródłowej i są wyświetlane tutaj wyłącznie w celach informacyjnych. Dodaj je do tej strony za pomocą edytora bloków.','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d lokalizowanych szablonów z motywu „%2$s” jest zachowanych w bazie danych, ale są obecnie nieaktywne. Ponownie staną się aktywne, jeśli ponownie aktywujesz ten motyw. Aby przenieść swoje tłumaczenia do nowego motywu, wygeneruj je ponownie za pomocą <strong>Ustawienia → Lingua Forge → Router → FSE scaffold</strong>.','Scanning posts for missing or out-of-sync featured images…'=>'Skanowanie postów w poszukiwaniu brakujących lub niezsynchronizowanych obrazów wyróżnionych…','Re-scanning…'=>'Ponowne skanowanie…','Scan failed: '=>'Nieudane skanowanie: ','unknown error'=>'nieznany błąd','Scan request failed. Please try again.'=>'Żądanie skanowania nie powiodło się. Spróbuj ponownie.','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ Nie znaleziono postów <strong>{lang}</strong>. Upewnij się, że wszystkie przetłumaczone posty mają ustawiony meta języka na <strong>{lang}</strong> w metaboxie języka.','✅ All <strong>{lang}</strong> featured images are already in sync with their source post. Scanned <strong>{scanned}</strong> post(s).'=>'✅ Wszystkie wyróżnione obrazy <strong>{lang}</strong> są już zsynchronizowane z ich postem źródłowym. Skanowane <strong>{scanned}</strong> posty.','Found <strong>{n}</strong> post(s) missing or out of sync with their source featured image, out of <strong>{scanned}</strong> scanned for <strong>{lang}</strong>.'=>'Znaleziono <strong>{n}</strong> post(ów) brakujących lub niezgodnych z ich źródłowym obrazem wyróżniającym, spośród <strong>{scanned}</strong> przeskanowanych dla <strong>{lang}</strong>.','Post'=>'Post','Current'=>'Obecny','Source (EN)'=>'Termin źródłowy','None'=>'Brak','Copy from source'=>'Skopiuj ze źródła','Copying…'=>'Kopiowanie…','✅ Copied'=>'✅ Skopiowano','❌ 